window.COURSE = {"meta":{"title":"Скорочтение за 14 дней","subtitle":"Интерактивный курс: 20 минут в день, миссии и честные замеры","tagline":"Не «1000 слов в минуту», а чтение с пониманием — быстрее, чем вчера.","days":14,"minutes":20,"version":"1.0","note":"Курс собран на основе известных исследований чтения, внимания и памяти. Все упражнения имеют проверяемый результат: скорость без понимания не засчитывается."},"phases":[{"id":1,"title":"Настройка","days":"1–3","desc":"Диагностика, поле зрения и внутренний голос. Убираем то, что мешает по умолчанию.","color":"#3b6ef5"},{"id":2,"title":"Механика","days":"4–8","desc":"Возвраты, смысловые блоки, выборочное чтение, вопросы до текста, внешний темп.","color":"#0f9d76"},{"id":3,"title":"Смысл и память","days":"9–11","desc":"Карта текста, припоминание, интервалы, управление вниманием.","color":"#c2410c"},{"id":4,"title":"Интеграция","days":"12–14","desc":"Четыре режима чтения, проект на реальном тексте, финальный замер и план.","color":"#7c3aed"}],"ranks":[{"name":"Новичок","min":0},{"name":"Читатель","min":150},{"name":"Скороход","min":400},{"name":"Стратег","min":700},{"name":"Мастер","min":1050},{"name":"Гроссмейстер","min":1450},{"name":"Легенда","min":1800}],"achievements":[{"id":"first_lesson","title":"Первый шаг","desc":"Завершён первый урок","icon":"1"},{"id":"streak_3","title":"Три дня подряд","desc":"Серия из 3 дней","icon":"3"},{"id":"streak_7","title":"Неделя без пропусков","desc":"Серия из 7 дней","icon":"7"},{"id":"schulte_45","title":"Молниеносный поиск","desc":"Таблица Шульте 5×5 быстрее 45 секунд","icon":"⚡"},{"id":"speed_300","title":"Триста","desc":"300 слов/мин при понимании от 70%","icon":"→"},{"id":"speed_400","title":"Четыреста","desc":"400 слов/мин при понимании от 70%","icon":"⇒"},{"id":"comp_90","title":"Снайпер смысла","desc":"Понимание 90% и выше на замере","icon":"◎"},{"id":"boss_1","title":"Тихий взрыв","desc":"Побеждён босс фазы I","icon":"I"},{"id":"boss_2","title":"Понимание под скоростью","desc":"Побеждён босс фазы II","icon":"II"},{"id":"boss_3","title":"Финал","desc":"Пройден финальный замер","icon":"III"},{"id":"perfect_quiz","title":"Без ошибок","desc":"Проверка урока на 100%","icon":"✓"},{"id":"all_lessons","title":"Курс пройден","desc":"Все 14 уроков завершены","icon":"★"}],"cheat":{"formulas":[["Скорость чтения","слов/мин = количество слов ÷ время в минутах"],["Понимание","доля правильных ответов на вопросы по тексту, %"],["Эффективная скорость","слов/мин × понимание ÷ 100"],["Правило допуска","ускорение засчитывается, только если понимание ≥ 70%"]],"techniques":{"cols":["Техника","Что тренирует","Дозировка","Ограничение"],"rows":[["Таблицы Шульте","распределение внимания, периферийный поиск","3 подхода по 30–60 с","не заменяет чтение"],["Клиновидные таблицы","захват слов за одну фиксацию","5–7 строк, 30–40 с","только на простых словах"],["Счёт 1-2-3-4","снижение субвокализации","2–3 мин на простом тексте","не применять на сложном тексте"],["Метроном / пейсинг","преодоление плато темпа","2–5 мин","мешает понимать сложное"],["RSVP","узнавание слов, замер темпа","1–3 мин","нельзя вернуться назад"],["Чанкинг с разметкой","укрупнение фиксаций","1 абзац с метками, затем без","мельче блоки на сложном тексте"],["Один проход","сокращение регрессий","1 текст в день","возврат к абзацу разрешён"],["Сканирование","поиск факта","60–90 с по вопросу","цифру проверять в контексте"],["Просмотр (skimming)","быстрый сбор структуры","3 мин перед чтением","не заменяет чтение"],["SQ3R","понимание и удержание","10–20 мин на текст","не пропускать пересказ"],["Припоминание","долговременная память","2 мин после текста","сначала вспомнить, потом проверять"],["Интервалы 1–3–7–14","закрепление","4 повторения","нужны вопросы для проверки"],["Спринт 10–15 мин","концентрация","1–2 в день","телефон вне поля зрения"],["Карта текста","понимание связей","2 мин по памяти","не переписывать текст"],["3-2-1","расширение темпового диапазона","1 отрывок","проверять понимание после каждого прохода"]]},"myths":[{"m":"Можно читать 1000+ слов в минуту с полным пониманием","t":"Нет. При таком темпе текст просматривается фрагментами, а понимание падает. Реалистичный рост — в 1,5–2 раза."},{"m":"Нужно полностью отключить внутреннюю речь","t":"Вредно. Проговаривание помогает понимать сложные тексты. Его снижают только на простых текстах и временно."},{"m":"Чтение по диагонали экономит время","t":"Только для просмотра и поиска. Для договоров, формул и учебных текстов это потеря смысла."},{"m":"Гимнастика для глаз ускоряет чтение","t":"Слабые доказательства. Движения глаз — следствие навыка, а не его причина. Тренируется чтение, а не мышцы глаз."},{"m":"Фоточтение и «активация полушарий»","t":"Псевдонаука. Нет воспроизводимых данных о чтении страницы «сканированием» с последующим recall."},{"m":"Скорость важнее понимания","t":"Наоборот. Эффективная скорость = скорость × понимание. Без понимания рост скорости бессмыслен."},{"m":"Один интенсивный марафон заменяет ежедневную практику","t":"Нет. Навык держится на регулярной практике с обратной связью, а не на объёме за один раз."}],"rules":["Один день — один урок, 20 минут, в одно и то же время.","Читайте текст до конца, прежде чем оценивать понимание.","Всегда проверяйте смысл: вопросы — часть упражнения, а не формальность.","Начинайте с обзора: заголовки, введение, вывод.","Формулируйте вопросы до чтения.","Возврат к абзацу — стратегия, возврат к слову — привычка.","Сложный текст читайте медленнее. Это не регресс.","Записывайте результаты: без данных нет обратной связи.","Пауза с движением лучше паузы с телефоном.","Сравнивайте себя с собой вчерашним."],"glossary":[["Фиксация","остановка глаза на слове или группе слов во время чтения"],["Саккада","быстрый перескок глаза между фиксациями"],["Регрессия","возвратное движение глаза к уже прочитанному"],["Субвокализация","беззвучное проговаривание текста"],["Поле ясного видения","зона, в которой глаз различает детали; по краям — только контуры"],["Чанкинг","чтение смысловыми блоками по 2–4 слова"],["Сканирование","поиск конкретного факта в тексте"],["Просмотр (skimming)","быстрое чтение для общего смысла и структуры"],["SQ3R","стратегия: обзор, вопросы, чтение, пересказ, проверка"],["Эффективная скорость","скорость чтения с поправкой на понимание"],["Интервальное повторение","повторение через возрастающие промежутки"],["Остаток внимания","часть внимания, остающаяся на прежней задаче после переключения"]]},"texts":{"attention":{"title":"Внимание — это прожектор, а не ведро","text":"Внимание устроено как прожектор, а не как ведро. Мы не впитываем всё, что находится перед глазами: мозг выбирает несколько объектов и подавляет остальное. Именно поэтому человек может смотреть на страницу и не помнить ни строчки — глаза двигались, а прожектор был направлен в другую сторону.\n\nВыбор происходит быстро и почти незаметно. Если вы читаете и одновременно прислушиваетесь к разговору в соседней комнате, часть ресурса уходит на фильтрацию шума. Строка остаётся перед глазами, но её обработка идёт медленнее, а смысл ускользает. Отсюда простое правило: качество чтения определяется не только скоростью глаз, но и тем, сколько внимания осталось свободным.\n\nВнимание имеет ограниченный объём и восстанавливается не мгновенно. После переключения с сообщения на текст нужно время, чтобы вернуться в контекст. Чем чаще переключения, тем больше потерь. Поэтому короткие сосредоточенные подходы работают лучше, чем долгие попытки читать в шумной среде.\n\nЕсть и хорошая новость: внимание поддаётся тренировке. Оно улучшается, когда задача ясна, обратная связь быстрая, а отвлекающие факторы убраны. Именно на этом строится вся дальнейшая работа: сначала мы убираем помехи, затем учим глаз двигаться экономнее, и только потом добавляем скорость.\n\nЗамер, который вы сделаете сегодня, нужен не для оценки «хорошо или плохо». Он нужен как точка отсчёта. Через две недели вы сравните себя с собой — это единственное сравнение, которое здесь имеет смысл."},"sleep":{"title":"Зачем мозгу сон","text":"Сон часто воспринимают как паузу, но для мозга это рабочее время. Пока человек спит, нервная система продолжает обрабатывать информацию: одни связи усиливаются, другие ослабляются. Именно поэтому выученный вечером материал утром вспоминается лучше, чем сразу после занятия.\n\nВо сне мозг проходит несколько циклов, и каждый выполняет свою работу. В глубоком сне восстанавливаются ресурсы организма, в быстром сне активно работает память и воображение. Прерывать сон на середине цикла неприятно: человек просыпается разбитым, хотя формально спал достаточно.\n\nДля чтения и обучения сон важен по двум причинам. Во-первых, он закрепляет то, что было прочитано и осмыслено. Во-вторых, он восстанавливает внимание: невыспавшийся человек читает медленнее и хуже удерживает смысл. Тренировать скорость на фоне недосыпа почти бессмысленно — результат будет нестабильным.\n\nПрактический вывод прост. Если вы читаете сложный текст, не планируйте его на позднюю ночь. Лучше прочитать его днём, а перед сном коротко вспомнить главное. Мозг сделает часть работы без вашего участия.\n\nИ ещё одно: сон не заменяется кофеином. Кофеин блокирует сигнал усталости, но не восстанавливает ресурс. Это как закрыть лампочку «мало топлива» картонкой: индикатор не горит, а бак пустой."},"habits":{"title":"Петля привычки","text":"Привычка — это действие, которое выполняется почти без участия сознания. Психологи описывают её как петлю из трёх элементов: сигнал, действие и награда. Сигнал запускает поведение, действие его выполняет, награда сообщает мозгу, что путь был верным. Чем чаще петля повторяется, тем прочнее становится связь.\n\nДля обучения это удобно. Если каждый день в одно и то же время открывать курс на двадцать минут, сигналом становится время и место. Через несколько дней мозг начинает ждать занятия, и запуск перестаёт требовать силы воли. Именно поэтому ежедневная короткая практика надёжнее редких длинных рывков.\n\nВажно и то, что привычка привязана к среде. Чтение в шумной кухне и чтение за чистым столом — это два разных навыка, потому что сигналы разные. Пока новый режим не закрепился, помогают внешние опоры: закладка, таймер, наушники, одна и та же папка с материалами.\n\nНаграда не обязана быть большой. Достаточно отметить выполненное задание, увидеть рост полоски прогресса или записать результат в дневник. Мозгу важен сам факт завершения, а не размер приза.\n\nИ последнее: старую привычку почти невозможно удалить, но её можно заменить. Если вы привыкли проверять телефон при каждой паузе, предложите себе другую паузу — встать, посмотреть в окно, сделать три медленных вдоха. Новая петля строится рядом со старой и постепенно перекрывает её."},"music":{"title":"Почему мы отбиваем ритм","text":"Человек — единственный вид, который способен произвольно подстраиваться под ритм. Мы хлопаем в такт музыке, киваем головой, шагаем в ногу. Эта способность называется слухо-моторной синхронизацией, и она опирается на сети мозга, связывающие слух, движение и предсказание.\n\nРитм работает как внешний метроном для тела. Мозг предсказывает следующий удар и готовит движение заранее, поэтому нам кажется, что мы попадаем в такт без усилий. Чем предсказуемее ритм, тем легче синхронизация — отсюда простая структура популярных песен с чёткой долей.\n\nДля чтения это неожиданно полезно. Ритмичный внешний стимул задаёт темп и снижает внутреннюю болтовню: когда нужно попадать в удар, меньше ресурса остаётся на проговаривание слов. Именно поэтому метроном и ровный стук используются в тренировках скорости чтения.\n\nНо у приёма есть границы. Если текст сложный, внешний ритм начинает мешать: смысл требует пауз и возвратов. Поэтому метроном применяют на понятных текстах и короткими отрезками, а не как постоянный фон для любой книги.\n\nЕщё одно наблюдение: музыка с текстом конкурирует за речевые ресурсы. Песня со словами мешает читать сильнее, чем инструментальная. Если вам нужен фон, выбирайте предсказуемую инструментальную музыку или тишину — тишина по-прежнему самый надёжный вариант."},"city":{"title":"Города, в которых хочется идти","text":"Городская среда незаметно задаёт сценарий поведения. Широкая улица без переходов приглашает ехать, узкая с витринами — идти. Скамейки, деревья и короткие расстояния между дверями делают прогулку приятной, а пустые проспекты — утомительной, даже если идти недалеко.\n\nИсследователи городской среды давно заметили: людям нравится не «красивое» само по себе, а разнообразие и человеческий масштаб. Когда на первых этажах есть двери, окна и разные функции, идти интересно: каждые несколько метров меняется картинка. Монотонная стена давит, даже если она новая и чистая.\n\nВторой фактор — безопасность. Она складывается из мелочей: освещения, видимости, количества людей на улице, скорости транспорта. Перекрёсток с узкими полосами и островком безопасности воспринимается спокойнее, чем широкий проспект, который нужно перебегать.\n\nТретий фактор — связанность. Город удобен, когда из точки А в точку Б есть прямой и понятный путь. Разрывы, обходы и заборы превращают короткое расстояние в длинное приключение, и люди начинают брать машину там, где могли бы дойти пешком.\n\nИз этих наблюдений выросла практика «города для людей»: сужать полосы, добавлять деревья, убирать барьеры, развивать первые этажи. Споры о деталях продолжаются, но принцип устойчив: среда должна приглашать действие, а не требовать усилия."},"memory":{"title":"Память — не архив, а реконструкция","text":"Принято думать, что память похожа на склад: события лежат на полках, и мы просто достаём нужную коробку. На самом деле воспоминание каждый раз собирается заново из фрагментов: образов, слов, эмоций и ожиданий. Поэтому один и тот же эпизод разные люди описывают по-разному, и оба при этом искренне уверены в своей правоте.\n\nРеконструкция объясняет и ошибки. Когда мы вспоминаем, мозг дополняет пробелы наиболее вероятным вариантом. Если подсказать ложную деталь, она может встроиться в воспоминание и остаться там надолго. Именно так работают некоторые приёмы допроса, и именно поэтому свидетелей опрашивают аккуратно и по горячим следам.\n\nДля учёбы вывод парадоксальный: память укрепляется не тогда, когда мы читаем, а тогда, когда мы вспоминаем. Попытка закрыть книгу и пересказать главное — более сильное упражнение, чем ещё одно перечитывание. Ошибки при припоминании полезны: они показывают, где именно память проваливается.\n\nВторой вывод касается интервалов. Повторение через день, через три дня и через неделю даёт больше, чем пять повторений подряд. Между попытками воспоминание слабеет, и усилие по его восстановлению как раз и закрепляет след.\n\nТретий вывод — про смысл. Бессмысленный набор слов запоминается хуже, чем история с логикой. Если материал удаётся связать с тем, что вы уже знаете, он держится дольше. Поэтому вопросы «как это связано с моим опытом» и «что из этого следует» — не украшение, а рабочий инструмент."},"language":{"title":"Язык и мысль","text":"Спор о том, определяет ли язык мышление, длится столетия. Сильная версия — «нет слова, нет мысли» — не подтверждается: люди различают оттенки, для которых нет отдельного названия. Слабая версия ближе к истине: язык влияет на то, что мы замечаем и как быстро это называем.\n\nПример с цветом показателен. Носители языков, где синий и голубой обозначаются разными словами, быстрее различают эти оттенки в задаче на внимание. Разница не в зрении, а в привычке категоризации: название работает как ярлык, который ускоряет поиск.\n\nПохожая история с пространством. Одни языки описывают расположение через стороны света, другие — через «лево-право», третьи — через положение тела. Люди, привыкшие к абсолютным координатам, лучше ориентируются в незнакомой местности: язык тренирует навык, а навык влияет на язык.\n\nДля чтения это важно с практической стороны. Богатый словарь ускоряет понимание: знакомое слово узнаётся целиком, а не складывается по буквам. Чем больше слов вы встречали в разных контекстах, тем меньше пауз возникает при чтении.\n\nОтсюда простой вывод: скорость чтения растёт не только от упражнений для глаз. Она растёт от словарного запаса и от опыта встреч с разными типами текстов. Читать разнообразное — значит строить фундамент для быстрого чтения."},"reading":{"title":"Что происходит, когда мы читаем","text":"Чтение кажется плавным движением, но глаз движется рывками. Он задерживается на слове или группе слов примерно на четверть секунды, затем перескакивает дальше. Эти остановки называют фиксациями, а перескоки — саккадами. Во время саккады зрение почти отключено: мозг получает размытое пятно и достраивает картину.\n\nПоле ясного видения невелико. В центре мы различаем несколько букв, по краям — контуры и длину слов. Именно поэтому опытный читатель захватывает за одну фиксацию два-три коротких слова, а не одно. Границы этого поля можно расширять тренировкой, но не бесконечно.\n\nЕщё одна особенность — возвраты. Глаз часто откатывается назад, чтобы перечитать фразу. Иногда это оправдано, но чаще происходит автоматически, из-за неуверенности. Возвраты съедают заметную часть времени и почти не добавляют понимания.\n\nНаконец, внутренняя речь. Многие проговаривают слова про себя, и это помогает понимать сложные тексты. При быстром чтении проговаривание становится тормозом: язык не успевает за глазами. Поэтому тренировка состоит не в том, чтобы «отключить» внутренний голос навсегда, а в том, чтобы научиться управлять им по задаче.\n\nИз этих четырёх фактов — фиксации, поле зрения, возвраты, проговаривание — и складывается почти вся практика скорочтения. Всё остальное лишь надстройка."},"caffeine":{"title":"Кофеин: где заканчивается польза","text":"Кофеин не даёт энергии. Он блокирует рецепторы, которые сообщают мозгу об усталости. Аденозин накапливается в течение дня и постепенно тормозит нервную систему; кофеин занимает его место, и сигнал «пора отдыхать» не проходит. Бодрость при этом субъективна: ресурс не появился, просто выключился индикатор.\n\nПериод полувыведения кофеина у взрослого человека — около пяти часов, с большим разбросом. Это значит, что чашка в четыре дня к десяти вечера всё ещё наполовину в крови. Для многих людей это заметно ухудшает засыпание и качество глубокого сна, даже если субъективно они «спят нормально».\n\nПольза умеренных доз подтверждается для внимания и бдительности, особенно при недосыпе и монотонной работе. Для сложной творческой задачи эффект слабее: кофеин помогает не заснуть, но не делает мышление глубже. Ожидание «выпью и пойму сложный текст» часто не оправдывается.\n\nЕсть и обратная сторона: тревожность, учащённый пульс, дрожь, проблемы с желудком. У людей с повышенной чувствительностью даже небольшая доза даёт неприятные эффекты. Привыкание тоже реально: со временем та же доза бодрит слабее.\n\nПрактический вывод для занятий: не пытайтесь компенсировать кофеином недосып перед сложным чтением. Лучше короткий сон, вода и проветривание. А если пьёте кофе, помните о времени: последняя чашка — минимум за шесть-восемь часов до сна."},"movement":{"title":"Движение и мозг","text":"Физическая активность влияет на мозг не только через настроение. При движении улучшается кровоснабжение, меняется уровень нейромедиаторов, а регулярные нагрузки связывают с поддержкой памяти и внимания. Эффект скромный, но устойчивый: это не «таблетка для интеллекта», а фактор, который помогает системе работать ровнее.\n\nОсобенно заметна роль движения в перерывах. После десяти минут ходьбы или простой разминки внимание восстанавливается лучше, чем после десяти минут в телефоне. Причина проста: смена позы и мышечная работа снижают накопившееся напряжение, а сенсорный поток обновляет контекст.\n\nЕсть и менее очевидный эффект — связь движения с речью и ритмом. Ходьба задаёт ровный темп, и в этом состоянии легче думать и формулировать. Многие авторы отмечают, что структура абзаца приходит во время прогулки, а не за столом.\n\nДля курса это практическая рекомендация. Если чтение идёт тяжело, не увеличивайте усилие — сделайте паузу на две минуты и походите. Если нужно запомнить структуру текста, перескажите её вслух во время ходьбы. Если предстоит долгая работа, ставьте короткие двигательные паузы заранее, а не когда силы уже кончились.\n\nИ последнее: регулярность важнее интенсивности. Двадцать минут быстрой ходьбы каждый день дают больше, чем редкий изматывающий марафон."},"modes":{"title":"Служебная записка: подготовка квартального отчёта","text":"Кому: руководителям отделов. От: аналитического отдела. Тема: порядок подготовки квартального отчёта.\n\nСрок сдачи отчёта — пятнадцатое число месяца, следующего за отчётным кварталом. Черновики принимаются до десятого числа. Поздние материалы включаются в приложение и не влияют на итоговые выводы.\n\nСтруктура отчёта фиксирована. Раздел первый — ключевые показатели за квартал. Раздел второй — отклонения от плана с указанием причин. Раздел третий — риски следующего квартала. Раздел четвёртый — предложения по корректировке. Объём основного текста — не более восьми страниц, приложения не ограничены.\n\nДанные предоставляются в табличном виде. Формат файла — таблица с шапкой в первой строке. Пустые значения обозначаются прочерком, а не нулём. Итоговые строки выделяются полужирным. Диаграммы допускаются только для динамики за четыре квартала.\n\nСогласование проходит в два этапа. Сначала профильный руководитель проверяет факты, затем аналитический отдел проверяет методику расчёта. Замечания направляются одним письмом, а не серией сообщений. Срок ответа на замечания — два рабочих дня.\n\nОтветственный за сбор — Марина Ковалёва, внутренний номер 4312. Резервный ответственный — Игорь Лебедев, номер 4317. Вопросы по методике принимаются до пятого числа. Вопросы после сдачи рассматриваются только в порядке исключения.\n\nИтоговая версия публикуется в общем каталоге и дублируется в рассылке руководителям. Печатные копии не рассылаются."},"long_essay":{"title":"Что делает текст понятным","text":"Понятность текста кажется свойством самого текста, но на деле это отношение между текстом и читателем. Один и тот же абзац будет прозрачным для специалиста и непроницаемым для новичка. Поэтому вопрос «понятно ли написано» без указания аудитории не имеет ответа.\n\nТем не менее есть устойчивые признаки, которые облегчают понимание почти для всех. Первый — предсказуемая структура. Когда читатель знает, где введение, где аргумент, а где вывод, он тратит меньше усилий на ориентацию. Заголовки, короткие абзацы и явные связки работают как разметка на дороге.\n\nВторой признак — знакомые слова в незнакомых сочетаниях. Текст не должен избегать терминов, но обязан объяснять их при первом появлении. Термин без объяснения — это точка, в которой читатель либо останавливается, либо начинает догадываться, и оба варианта стоят времени.\n\nТретий признак — конкретность. Абстракция требует перевода в образ, и этот перевод делает читатель. «Оптимизация процессов» — это задача, «сократить согласование с пяти дней до двух» — это действие. Конкретика не упрощает мысль, она делает её проверяемой.\n\nЧетвёртый признак — ритм. Длинные предложения утомляют не сами по себе, а своей однородностью. Чередование коротких и длинных фраз помогает удержать внимание. Письменная речь, в которой нет пауз, читается как непрерывный гул.\n\nПятый признак — избыточность. Хороший текст повторяет главное разными способами: в заголовке, в примере, в выводе. Это не вода, а страховка: если читатель пропустил одну формулировку, он встретит вторую.\n\nШестой признак — честная сложность. Если тема трудная, текст не должен притворяться простым. Лучше признать: «здесь три условия, и все важны». Читатель прощает сложность, но не прощает обмана.\n\nОтсюда практический вывод для того, кто учится читать быстро. Скорость не отменяет структуру: сначала полезно посмотреть на заголовки и выводы, затем прочитать основной текст, затем проверить, совпала ли ваша карта с авторской. Быстрое чтение без предварительного обзора похоже на поездку по незнакомому городу без карты: движение есть, понимания мало.\n\nИ ещё: понятность растёт, когда читатель задаёт вопросы. Текст, прочитанный с вопросом «что автор доказывает и чем», запоминается лучше, чем текст, прочитанный ровно и без цели. Вопрос превращает пассивное потребление в работу."},"final_essay":{"title":"Скорость и понимание","text":"Скорость чтения — не добродетель и не недостаток. Это параметр, который имеет смысл только вместе с целью. Просмотреть список новостей и изучить договор — разные задачи, и одинаковый темп здесь был бы ошибкой.\n\nПредел скорости задан не глазами, а обработкой смысла. Глаз может перескакивать быстро, но понимание требует связывания нового с уже известным. Когда темпа больше, чем выдерживает понимание, чтение превращается в имитацию: страницы перелистываются, след остаётся слабый.\n\nПоэтому главная метрика — не слова в минуту, а эффективная скорость: сколько слов в минуту вы прочитали с приемлемым пониманием. Если после ускорения понимание падает ниже семидесяти процентов, ускорение не считается достижением.\n\nРеалистичный прогресс за две-три недели тренировок — полтора-два раза к исходному темпу при сохранении понимания. Более смелые обещания обычно достигаются за счёт пропуска текста, а не за счёт более эффективного чтения.\n\nЧто действительно работает: убрать возвраты, расширить захват слова за одну фиксацию, заранее просматривать структуру, задавать вопросы до чтения, проверять себя после. Что работает хуже: гимнастика для глаз, «активация полушарий», попытки читать по диагонали сложные тексты.\n\nИ последнее. Навык держится, пока есть практика. Двадцать минут в день с обратной связью дают больше, чем месяц интенсивных упражнений и год без чтения."},"focus":{"title":"Цена многозадачности","text":"Многозадачность — удобная иллюзия. Человек не выполняет два дела одновременно: он переключается между ними, и каждое переключение стоит времени. Вождение с разговором по телефону, чтение с проверкой сообщений, работа с двумя вкладками — всё это последовательность переключений, а не параллельные процессы.\n\nОсобенно дорого переключение стоит там, где нужно удерживать контекст. Программист, прерванный на середине функции, возвращается не к той же точке, а к чуть более размытой версии задачи. Читатель, отвлёкшийся на сообщение, тратит несколько секунд на то, чтобы вспомнить, о чём был абзац.\n\nЕсть и эффект накопления. Если переключения частые, мозг остаётся в состоянии готовности к прерыванию и хуже погружается в задачу. Субъективно это ощущается как «не могу сосредоточиться», хотя на самом деле внимание просто разогнано в режим ожидания.\n\nЧто помогает. Первое — определить одну задачу на отрезок времени и убрать всё, что может её прервать. Второе — записывать внезапные мысли, а не бросаться их выполнять. Третье — делать паузы между блоками, чтобы контекст успевал закрыться.\n\nИ честная оговорка: полностью изолироваться невозможно, да и не нужно. Цель не в стерильной тишине, а в том, чтобы переключения были выбором, а не фоном. Разница между «я решил проверить сообщение» и «рука сама потянулась к телефону» — и есть разница между управлением и реакцией."},"practice":{"title":"Осознанная практика","text":"Осознанная практика отличается от простого повторения тремя вещами: конкретной целью, обратной связью и работой на границе возможностей. Если вы просто читаете больше, вы закрепляете то, что уже умеете, включая ошибки. Если вы ставите узкую задачу и сразу проверяете результат, навык меняется.\n\nЦель должна быть проверяемой. «Читать быстрее» — не цель. «Прочитать этот текст без возвратов и уложиться в триста слов в минуту» — цель. Узкая задача сужает внимание и делает результат измеримым; широкие намерения быстро размываются.\n\nОбратная связь нужна быстрая. В чтении её роль играют вопросы по тексту: они показывают, что вы на самом деле поняли. Без проверки ускорение ощущается как прогресс, даже когда понимание падает. Именно поэтому замер и вопросы — не бюрократия, а часть метода.\n\nТретье условие — посильная сложность. Задача должна быть чуть труднее текущего уровня: слишком лёгкая не тренирует, слишком трудная ломает мотивацию. Хороший признак — вы ошибаетесь, но понимаете, в чём именно.\n\nИ последнее: осознанная практика утомляет. Она требует концентрации, поэтому короткие подходы по пятнадцать-двадцать минут работают лучше, чем многочасовые сессии. Усталость — сигнал, что пора сделать паузу, а не что нужно терпеть."},"doc_schedule":{"title":"Программа конференции «Текст и внимание»","text":"Программа конференции «Текст и внимание». 14 марта, корпус Б, второй этаж.\n\n09:00 — регистрация, холл у зала 204. Кофе с 09:15.\n09:30 — открытие. Зал 204. Приветствие организаторов, 10 минут.\n10:00 — пленарный доклад «Как читает глаз». Зал 204. Докладчик: А. Ветров. 45 минут, вопросы 15 минут.\n11:00 — секция 1: «Внимание и среда». Аудитория 210. Три доклада по 20 минут.\n11:00 — секция 2: «Текст для экрана». Аудитория 212. Четыре доклада по 15 минут.\n12:30 — обед. Столовая на первом этаже, вход по бейджу.\n13:30 — мастер-класс «Таблицы Шульте: мифы и практика». Зал 208. Ведущая: М. Ковалёва. Мест 24, запись у стойки.\n13:30 — круглый стол «Скорость против понимания». Зал 204. Участие по приглашению.\n15:00 — кофе-брейк, холл.\n15:20 — секция 3: «Память и повторение». Аудитория 210. Пять докладов по 12 минут.\n17:00 — заключительный доклад «Что мы знаем о чтении в 2026 году». Зал 204. 40 минут.\n18:00 — закрытие. Сертификаты выдаются на стойке регистрации до 19:00.\n\nМатериалы конференции публикуются на сайте 20 марта. Видеозаписи пленарных докладов — до 1 апреля. Вопросы организаторам принимаются на стойке регистрации, ответ в течение двух рабочих дней."},"ocean":{"title":"Океан как климатическая машина","text":"Океан кажется неподвижной массой, но он постоянно движется. Ветры гонят поверхностные воды, приливы поднимают и опускают уровень у берегов, а в глубине медленно циркулируют холодные массы. Эта циркуляция переносит тепло от экватора к полюсам и смягчает климат на больших территориях.\n\nКлючевую роль играет разница плотности. Холодная и солёная вода тяжелее тёплой и пресной, поэтому она опускается вниз, а на её место приходит вода с поверхности. Так возникает глобальный конвейер, который движется столетиями. Если в полярных морях образуется больше пресной воды, плотность падает, и течение может замедлиться.\n\nОкеан также поглощает значительную часть углекислого газа, который попадает в атмосферу. Растворённый газ используют морские организмы, а часть уходит в глубину вместе с опускающейся водой. Это не бесконечный резервуар: при нагревании вода хуже удерживает газы.\n\nНаблюдать за океаном сложно. Буи, спутники и автономные аппараты дают данные о температуре и солёности, но покрытие остаётся неравномерным. Поэтому модели климата опираются на комбинацию измерений и физических законов, а не на отдельные точки.\n\nДля читателя здесь важна привычка: за простыми утверждениями о «глобальном потеплении» стоят длинные цепочки измерений, допущений и поправок. Понимать их — значит читать не только вывод, но и метод."},"bees":{"title":"Танец пчёл","text":"Пчела-разведчица, найдя источник нектара, возвращается в улей и сообщает о находке не словами, а движением. Она бегает по сотам по фигуре, похожей на восьмёрку, и покачивает брюшком на прямом участке. Этот танец действительно передаёт информацию.\n\nНаправление указывает угол относительно солнца. Если корм находится строго по направлению к солнцу, пчела танцует вертикально вверх; если в противоположную сторону — вниз. Угол между вертикалью и направлением танца соответствует углу между солнцем и кормом.\n\nДлительность покачивания кодирует расстояние. Чем дальше источник, тем дольше пчела вибрирует. Точность не абсолютная: танец сообщает примерное направление и дистанцию, а дальше разведчицы ищут сами, ориентируясь на запах.\n\nТанец работает в темноте улья, где пчёлы не видят солнца. Они воспринимают вибрации и направление движения в пространстве сот, а также чувствуют запах, принесённый на теле разведчицы.\n\nИсследования танца — пример того, как наблюдение за поведением дополняет лабораторные опыты. Пчела не «думает» словами, но её сигнал достаточно информативен, чтобы десятки насекомых действовали согласованно. Это не язык в человеческом смысле, а эффективная система координации."},"chess":{"title":"Почему шахматы считают игрой расчёта","text":"В шахматах выигрывает не тот, кто быстрее двигает фигуры, а тот, кто лучше считает варианты и оценивает позицию. Однако чистый перебор невозможен: число ходов растёт лавинообразно, и даже мощные программы используют отсечения, а не полный перебор.\n\nОпытный игрок считает не все ходы подряд, а несколько осмысленных. Он опирается на типовые позиции, которые видел раньше: узнавание структуры заменяет часть вычислений. Именно поэтому гроссмейстер может быстро отбросить плохие продолжения.\n\nПамять в шахматах работает как библиотека шаблонов. Игрок запоминает не отдельные ходы, а связки: ослабленный король, открытая линия, пешечная структура. Чем богаче библиотека, тем меньше нужно считать с нуля.\n\nРасчёт требует дисциплины. Нужно удерживать в голове дерево вариантов, не путать ходы и вовремя останавливаться. Ошибки чаще происходят не от незнания, а от усталости и потери контроля.\n\nЕсть и обратная сторона: шаблоны могут подвести, если позиция нестандартная. Сильные игроки специально тренируют умение замечать, когда знакомый образец не работает.\n\nШахматы хорошо показывают разницу между скоростью и качеством. Быстрый ответ без расчёта выглядит уверенно, но проигрывает продуманному. В чтении это работает так же: скорость без понимания — красивый жест, а не результат."},"architecture":{"title":"Свет и масштаб в архитектуре","text":"Архитектура начинается не с фасада, а с ощущения пространства. Человек оценивает комнату по высоте потолка, ширине прохода и количеству света. Те же размеры могут казаться уютными или давящими в зависимости от пропорций.\n\nСвет меняет восприятие сильнее, чем отделка. Мягкий рассеянный свет делает помещение спокойным, резкий контраст — тревожным. Окно, расположенное высоко, даёт больше отражённого света и меньше бликов на рабочей поверхности.\n\nМасштаб задаётся телом. Ширина коридора, высота ступени, расстояние между поручнем и стеной — всё это подгоняется под человека. Когда пропорции нарушены, пространство кажется неудобным, даже если визуально красиво.\n\nМатериалы влияют на акустику и тактильность. Камень и бетон отражают звук, дерево и текстиль поглощают. В библиотеке важна тишина, в столовой — оживлённый фон; одна и та же планировка может звучать по-разному.\n\nСовременная практика всё чаще говорит о гибкости: пространство должно допускать разные сценарии. Стол, который можно переставить, и перегородка, которую можно убрать, продлевают жизнь помещению.\n\nХорошая архитектура не привлекает внимание к себе. Она делает действие удобным: читать, работать, разговаривать. Заметной она становится тогда, когда мешает."},"navigation":{"title":"Как люди находят дорогу","text":"Навигация — это не только карта. Человек ориентируется по ориентирам, солнцу, звукам и памяти о маршруте. Карта помогает, но решение принимается в конкретной точке: повернуть, подождать, вернуться.\n\nГородские ориентиры работают как якоря. Высокое здание, мост, площадь, необычная вывеска запоминаются легче, чем череда одинаковых перекрёстков. Поэтому навигационные приложения часто называют не улицы, а заметные объекты.\n\nВ лесу и на море ориентируются иначе. Там помогают солнце, звёзды, ветер, рельеф и следы. Опытный путешественник держит в голове не картинку, а последовательность признаков: с какой стороны мшистый ствол, куда течёт ручей, где садится солнце.\n\nОшибки навигации типичны. Люди переоценивают симметрию и недооценивают расстояние; уверены, что помнят поворот, хотя помнят лишь ощущение. Усталость и спешка ухудшают ориентирование сильнее, чем плохая карта.\n\nЦифровые карты снимают часть нагрузки, но создают новую: внимание уходит на экран, а среда перестаёт запоминаться. Если телефон разрядится, маршрут исчезнет вместе с ним.\n\nПрактический вывод прост. Перед дорогой посмотрите не только линию маршрута, но и два-три ориентира. Запомните направление движения и одну запасную точку. Этого часто достаточно, чтобы не потеряться."},"kid_sun":{"title":"Солнце","text":"Солнце — это огромная звезда. Оно светит и греет, поэтому на Земле есть день. Без солнца было бы темно и очень холодно.\n\nСолнечный свет помогает растениям расти. Трава, деревья и цветы поворачивают листья к свету. Люди тоже любят солнце, но долго быть на жаре нельзя: можно обгореть.\n\nУтром солнце поднимается, вечером опускается. Так происходит потому, что Земля вращается. Мы этого не замечаем, но Земля всё время кружится, как волчок."},"kid_cats":{"title":"Котята","text":"У кошки родились котята. Они маленькие, слепые и почти не слышат. Первые дни они только едят и спят, прижавшись к маме.\n\nЧерез неделю котята открывают глаза. Мир для них большой и шумный. Они учатся ходить, падают, встают и пробуют всё на зуб.\n\nКошки мурлычут, когда им спокойно. А ещё мурлыканье помогает им успокоиться. Если котёнок шипит и прячется, значит, он боится. Его не надо трогать, пусть привыкнет."},"kid_river":{"title":"Река","text":"Река начинается с маленького ручья. Он бежит с гор, собирает воду и постепенно становится широким.\n\nВода в реке всё время движется. Она несёт песок, ветки и листья. Камни на дне обтачиваются и становятся гладкими.\n\nРека поит животных и людей. На её берегах строят дома и сады. Но реку надо беречь: мусор в воде вредит рыбам и птицам. Чистая вода — это дом для многих живых существ."},"kid_stars":{"title":"Звёзды","text":"Ночью на небе видны звёзды. Они кажутся маленькими, но на самом деле звёзды огромные и очень далёкие.\n\nНаше Солнце — тоже звезда. Просто оно близко, поэтому кажется большим и ярким.\n\nЗвёзды собираются в группы. Люди придумали им названия и соединили линиями. Так появились созвездия. По звёздам раньше находили дорогу путешественники.\n\nЕсли долго смотреть на небо, глаза привыкают к темноте, и звёзд становится видно больше."},"kid_bike":{"title":"Велосипед","text":"Велосипед едет, когда человек крутит педали. Сила передаётся на колесо, и оно катится.\n\nЧтобы не упасть, надо держать равновесие. Сначала помогают боковые колёса, потом их снимают. Падать при обучении — нормально.\n\nПеред поездкой проверяют тормоза и шины. На дороге важно смотреть по сторонам и надевать шлем. Велосипед любит уход: чистая цепь и подкачанные колёса делают поездку легче."},"kid_rain":{"title":"Дождь","text":"Дождь начинается, когда в облаке собираются капельки. Они становятся тяжёлыми и падают вниз.\n\nКапли бывают разными: мелкая морось, крупный ливень, ледяной град. Град получается, когда капли замерзают в холодном воздухе.\n\nПосле дождя воздух становится чище: пыль оседает на землю. Лужи высыхают, а вода уходит в землю.\n\nРастениям дождь нужен, как еда. Без воды они вянут. Поэтому садовники радуются дождю, если он не слишком сильный."}},"lessons":[{"day":1,"phase":1,"title":"Старт: измеряем, а не угадываем","subtitle":"Точка отсчёта и правила игры","goal":"Получить три честных числа — скорость, понимание, эффективную скорость — и настроить рабочее место.","minutes":20,"fig":"img/fig_metrics.png","fig_caption":"Три метрики курса. Эффективная скорость = скорость × понимание.","theory":[{"h":"Три числа, которые важны","p":"Скорость чтения измеряют в словах в минуту (слов/мин). Но сама по себе она ничего не значит: текст можно пролистать за минуту и не понять ни абзаца. Поэтому рядом всегда стоит второе число — понимание в процентах, доля правильных ответов на вопросы по тексту. Третье число — эффективная скорость: скорость, умноженная на понимание. Если вы читаете 240 слов/мин с пониманием 60%, эффективная скорость равна 144. Именно она показывает, сколько смысла вы получаете в минуту."},{"h":"Зачем замер в начале","p":"Улучшать можно только то, что измерено. Сегодняшний результат — не оценка способностей, а точка отсчёта. Через две недели вы сравните себя с собой; сравнение с чужими рекордами здесь бесполезно, потому что тексты, цели и опыт у всех разные."},{"h":"Как устроено занятие","p":"Каждый день — около 20 минут: короткая теория, 2–3 тренажёра, проверка и минута на дневник. Заниматься лучше в одно и то же время: привычка запускается сигналом, а не силой воли."}],"bullets":["Читайте в обычном для вас темпе, с установкой «понять», а не «показать рекорд».","Во время замера не возвращайтесь к прочитанному и не заглядывайте в текст, отвечая на вопросы.","Один день — один урок. Пропуск не обнуляет навык, но серия дней — ваш главный союзник."],"exercises":[{"type":"measure","title":"Замер №1: базовая скорость","xp":40,"instruction":"Нажмите «Старт», прочитайте текст один раз в комфортном темпе и нажмите «Готово». Затем ответьте на вопросы, не возвращаясь к тексту.","params":{"textKey":"attention","label":"База","targetWpm":0,"minComp":0,"questions":[{"q":"С чем автор сравнивает внимание?","options":["С ведром","С прожектором","С фильтром"],"a":1,"explain":"Внимание выбирает объекты и подавляет остальное — как прожектор."},{"q":"Почему человек может смотреть на страницу и не помнить строчку?","options":["Глаза двигались, а внимание было направлено в другую сторону","Страница была плохо напечатана","Он читал слишком быстро"],"a":0,"explain":"Движение глаз без внимания не даёт понимания."},{"q":"Что нужно, чтобы вернуться в контекст после переключения?","options":["Время","Кофеин","Более быстрый темп"],"a":0,"explain":"Переключение оставляет «остаток внимания», контекст восстанавливается не мгновенно."},{"q":"Что улучшает внимание по тексту?","options":["Ясная задача и быстрая обратная связь","Постоянный шум","Многозадачность"],"a":0,"explain":"Ясная цель и обратная связь — условия тренировки внимания."},{"q":"Для чего нужен сегодняшний замер?","options":["Чтобы сравнить себя с другими","Чтобы получить точку отсчёта для сравнения с собой","Чтобы сразу поставить рекорд"],"a":1,"explain":"Сравнение с собой — единственное осмысленное."}]}},{"type":"reflection","title":"Зачем мне это","xp":20,"instruction":"Сформулируйте три конкретные ситуации, где вам нужна скорость чтения. Не «для развития», а «что именно я прочитаю иначе».","params":{"prompt":"Три ситуации, где мне нужна скорость чтения","placeholder":"Например: за неделю разобрать 40 страниц регламента; читать статьи по специальности; успевать за учебной программой…","minChars":40}},{"type":"checklist","title":"Рабочее место","xp":20,"instruction":"Проверьте пункты. Это не формальность: среда запускает привычку.","params":{"items":["Есть ровная поверхность и стул, за которым можно сидеть 20 минут","Телефон убран из поля зрения или в режиме «не беспокоить»","Свет падает на текст, а не в глаза","Есть таймер и место для записей","Я знаю, в какое время завтра открою курс"]}},{"type":"reader","title":"Второй текст: читаем с пониманием","xp":20,"optional":true,"instruction":"Прочитайте текст в удобном темпе и ответьте на вопросы. Это повторный проход после базового замера.","params":{"textKey":"habits","mode":"plain","questions":[{"q":"Из каких элементов состоит петля привычки?","options":["Сигнал, действие, награда","Цель, план, отчёт","Мотив, воля, результат"],"a":0,"explain":"Три звена: сигнал запускает, действие выполняется, награда закрепляет."},{"q":"Почему ежедневная короткая практика надёжнее редких рывков?","options":["Сигнал закрепляется, запуск перестаёт требовать воли","Так меньше устают глаза","Короткие тексты легче"],"a":0,"explain":"Привычка привязана к сигналу времени и места."},{"q":"Что делать со старой привычкой?","options":["Удалить навсегда","Заменить новой","Игнорировать"],"a":1,"explain":"Старую петлю почти нельзя стереть, но можно перекрыть новой."}]}}],"quiz":{"xp":30,"questions":[{"q":"Вы читаете 300 слов/мин с пониманием 60%. Какова эффективная скорость?","options":["180","300","360"],"a":0,"explain":"300 × 0,6 = 180."},{"q":"Понимание упало до 50%. Что делать в первую очередь?","options":["Ещё ускориться","Снизить темп до уровня, где понимание возвращается","Читать больше текстов подряд"],"a":1,"explain":"Скорость без понимания — не результат, а имитация."},{"q":"Почему ежедневные 20 минут лучше одного занятия на 2 часа в неделю?","options":["Привычка и распределённая практика закрепляют навык","Так проще найти время","Длинные занятия запрещены"],"a":0,"explain":"Регулярность и интервалы важнее объёма за один раз."}]},"takeaway":"Записанная база — уже результат. Дальше вы будете её обгонять.","bonus":"Прочитайте сегодня любую статью с установкой «понять», а не «дочитать». Отметьте, где взгляд возвращался назад."},{"day":2,"phase":1,"title":"Поле зрения: таблицы Шульте и клин","subtitle":"Учимся захватывать больше за одну остановку глаза","goal":"Расширить зону, из которой глаз считывает информацию, и ускорить поиск.","minutes":20,"fig":"img/fig_span.png","fig_caption":"Поле ясного видения узкое; края страницы мы видим размыто, но используем для навигации.","theory":[{"h":"Глаз не скользит, а прыгает","p":"При чтении глаз делает остановки — фиксации — и перескоки — саккады. За одну фиксацию опытный читатель схватывает не одну букву, а группу: чем шире «пятно ясности», тем меньше остановок нужно на строку. Скорость чтения растёт не потому, что глаз двигается быстрее, а потому, что остановок становится меньше."},{"h":"Таблицы Шульте","p":"Это квадрат с числами от 1 до 25, расположенными в случайном порядке. Задача — находить числа по порядку, удерживая взгляд в центре таблицы и работая периферией. Упражнение тренирует распределение внимания и скорость поиска, а не остроту зрения. Норматив для новичка — около 55–60 секунд, для уверенного уровня — 40 секунд и меньше."},{"h":"Клиновидные таблицы","p":"Здесь строки постепенно расширяются: от одной цифры до длинной последовательности. Взгляд держится в центре, а края строки считываются боковым зрением. Это упражнение на расширение захвата, и оно особенно полезно перед чтением текстов с короткими словами."}],"bullets":["Голову не поворачивайте: работают только глаза.","Если теряете число — вернитесь к центру, а не начинайте заново.","Три подхода по 30–40 секунд эффективнее одного длинного."],"exercises":[{"type":"schulte","title":"Таблица Шульте 5×5","xp":30,"instruction":"Нажимайте числа по порядку от 1 до 25. Старайтесь не водить взглядом по всей таблице: держите центр и находите числа боковым зрением. Три подхода.","params":{"size":5,"rounds":3,"targetSec":55}},{"type":"wedge","title":"Клин: расширяем захват","xp":20,"instruction":"Читайте строки вслух, удерживая взгляд в центре. Каждая следующая строка длиннее. Засеките время на все строки.","params":{"rows":7,"targetSec":35}},{"type":"schulte","title":"Контрольный подход","xp":10,"instruction":"Ещё одна таблица — на этот раз без установки на рекорд. Следите за тем, чтобы глаза двигались ровно, без суеты.","params":{"size":5,"rounds":1,"targetSec":60}},{"type":"schulte","title":"Шульте 6×6","xp":20,"optional":true,"instruction":"Усложнённый вариант: 36 чисел. Взгляд в центре, голову не поворачивайте.","params":{"size":6,"rounds":1,"targetSec":90}}],"quiz":{"xp":30,"questions":[{"q":"Сколько слов захватывает за одну фиксацию тренированный читатель?","options":["Одно","Два-три коротких слова","Строку целиком"],"a":1,"explain":"Захват растёт до 2–3 слов, но не до строки."},{"q":"Что тренируют таблицы Шульте?","options":["Остроту зрения","Распределение внимания и скорость поиска","Скорость проговаривания"],"a":1,"explain":"Это упражнение на внимание и периферийный поиск."},{"q":"Как называется возврат глаза назад по тексту?","options":["Саккада","Регрессия","Фиксация"],"a":1,"explain":"Регрессия — возвратное движение, о ней поговорим на четвёртый день."}]},"takeaway":"Меньше остановок — больше текста за то же время.","bonus":"По дороге куда-нибудь находите взглядом предметы по алфавиту: а — аптека, б — банк… Это та же тренировка периферии в реальной среде."},{"day":3,"phase":1,"title":"Внутренний голос: управляемая субвокализация","subtitle":"Проговаривание помогает — и мешает. Учимся переключать","goal":"Научиться снижать внутреннее проговаривание на простых текстах, не теряя смысла.","minutes":20,"fig":"img/fig_voice.png","fig_caption":"Три канала обработки текста. Проговаривание — не враг, а регулируемый ресурс.","theory":[{"h":"Что такое субвокализация","p":"Это беззвучное проговаривание слов во время чтения. Оно связано с работой речевых зон мозга и помогает удерживать смысл: сложные, непривычные фразы мы «слышим» внутренним голосом. Полностью отключить его нельзя и не нужно — на трудном тексте это ухудшит понимание."},{"h":"Где оно мешает","p":"Речь человека устроена примерно на 250–300 слов в минуту. Если глаза пытаются идти быстрее, внутренний голос становится тормозом: вы читаете не быстрее, чем говорите. На простых текстах — новостях, знакомых темах — проговаривание можно частично вытеснить."},{"h":"Три рабочих приёма","p":"Первый — счёт: читая, произносите про себя «один-два-три-четыре» в ровном темпе. Речевой канал занят, и проговаривать текст становится труднее. Второй — внешний ритм: метроном или постукивание задают темп. Третий — «ммм»: тяните ровный звук, пока читаете. Главное правило: приём включается на 2–3 минуты и только на простом тексте."}],"bullets":["Не пытайтесь «убить» внутренний голос навсегда.","Сложный текст, формулы, договор — читайте с проговариванием.","После упражнения всегда проверяйте понимание: без проверки тренируется не чтение, а имитация."],"exercises":[{"type":"reader","title":"Чтение со счётом","xp":30,"instruction":"Проговаривайте про себя «один-два-три-четыре» — по одному числу на удар метронома (каждые 0,62 с). Одновременно читайте текст. Числа не связаны со словами: это два независимых потока, и счёт занимает речевой канал. Через 2–3 минуты нажмите «Готово» и ответьте на вопросы — так вы проверите, что понимание сохранилось.","params":{"textKey":"sleep","mode":"count","questions":[{"q":"Что происходит с выученным материалом во сне?","options":["Он стирается","Он закрепляется","Он не меняется"],"a":1,"explain":"Сон участвует в консолидации памяти."},{"q":"Почему невыспавшийся человек читает хуже?","options":["Страдает внимание и удержание смысла","У него хуже зрение","Он быстрее проговаривает"],"a":0,"explain":"Сон восстанавливает внимание."},{"q":"Заменяет ли кофеин сон?","options":["Да, полностью","Нет, он только блокирует сигнал усталости","Только утром"],"a":1,"explain":"Кофеин маскирует усталость, но не восстанавливает ресурс."}]}},{"type":"reader","title":"Чтение под внешний темп","xp":30,"instruction":"Текст подсвечивается в заданном темпе. Держитесь за подсветку, не обгоняйте и не отставайте. Затем — проверка.","params":{"textKey":"sleep","mode":"pacer","wpm":300,"questions":[{"q":"Сколько циклов сна упоминает текст?","options":["Два","Несколько, включая глубокий и быстрый","Один"],"a":1,"explain":"Глубокий и быстрый сон выполняют разную работу."},{"q":"Что делать со сложным текстом вечером?","options":["Читать до результата","Прочитать днём, а вечером коротко вспомнить главное","Отложить на месяц"],"a":1,"explain":"Сон закрепит то, что вы вспомнили перед ним."},{"q":"Почему просыпаться в середине цикла неприятно?","options":["Цикл не завершён","Мешает свет","Организм привык"],"a":0,"explain":"Прерывание цикла даёт ощущение разбитости."}]}},{"type":"measure","title":"Босс фазы I: тихий взрыв","xp":100,"instruction":"Первый бой. Прочитайте текст, не проговаривая слова, и ответьте на вопросы. Победа — от 320 слов/мин при понимании от 70%.","params":{"textKey":"focus","label":"Босс I","targetWpm":320,"minComp":70,"boss":true,"questions":[{"q":"Что происходит при многозадачности на самом деле?","options":["Переключение между задачами","Параллельная работа","Ускорение обеих задач"],"a":0,"explain":"Мозг переключается, а не работает параллельно."},{"q":"Почему прерывание дорого стоит?","options":["Тратится время на восстановление контекста","Портится зрение","Ускоряется речь"],"a":0,"explain":"Контекст восстанавливается не мгновенно."},{"q":"Что происходит при частых переключениях?","options":["Мозг остаётся в режиме ожидания прерывания","Внимание становится устойчивее","Память улучшается"],"a":0,"explain":"Отсюда ощущение «не могу сосредоточиться»."},{"q":"Что помогает удержать задачу?","options":["Записывать внезапные мысли и возвращаться","Держать телефон рядом","Работать в двух вкладках"],"a":0,"explain":"«Парковка мыслей» снижает переключения."},{"q":"В чём разница между управлением и реакцией?","options":["Переключение по решению или автоматически","В скорости чтения","В количестве задач"],"a":0,"explain":"Осознанный выбор против импульса."}]}},{"type":"reader","title":"Счёт на другом тексте","xp":20,"optional":true,"instruction":"Ещё один проход со счётом «один-два-три-четыре» — теперь на другом тексте.","params":{"textKey":"music","mode":"count","questions":[{"q":"Как называется способность подстраиваться под ритм?","options":["Слухо-моторная синхронизация","Абсолютный слух","Ритмическая память"],"a":0,"explain":"Связь слуха, движения и предсказания."},{"q":"Почему ритм помогает читать быстрее?","options":["Занимает речевой канал и задаёт темп","Улучшает зрение","Ускоряет дыхание"],"a":0,"explain":"Меньше ресурса остаётся на проговаривание."},{"q":"Когда внешний ритм мешает?","options":["На сложном тексте","На простом тексте","Никогда"],"a":0,"explain":"Смысл требует пауз и возвратов."}]}}],"quiz":{"xp":30,"questions":[{"q":"Когда субвокализацию стоит снижать?","options":["На сложном договоре","На простом знакомом тексте","Всегда, это главный враг"],"a":1,"explain":"Только там, где смысл не требует внутренней речи."},{"q":"Зачем нужен счёт во время чтения?","options":["Чтобы занять речевой канал","Чтобы считать слова","Чтобы ускорить глаза"],"a":0,"explain":"Речевой канал занят — проговаривать труднее."},{"q":"Что обязательно после упражнения на субвокализацию?","options":["Проверка понимания","Повтор упражнения ещё пять раз","Замер скорости глаз"],"a":0,"explain":"Без проверки вы тренируете скорость без смысла."}]},"takeaway":"Внутренний голос — регулятор, а не помеха. Учитесь включать и выключать его по задаче.","bonus":"Посчитайте, сколько слов в минуту вы говорите вслух в обычном темпе. Это ваш «речевой потолок»: пока чтение медленнее — вы читаете голосом."},{"day":4,"phase":2,"title":"Регрессии: читаем один раз","subtitle":"Убираем возвраты и лишние остановки","goal":"Сократить число возвратных движений глаза при чтении.","minutes":20,"fig":"img/fig_eye.png","fig_caption":"Траектория глаза: фиксации, саккады и возврат назад — регрессия.","theory":[{"h":"Что такое регрессия","p":"Регрессия — возврат глаза к уже прочитанному. Иногда она оправдана: проверить цифру, перечитать формулу. Но чаще это автоматическая привычка, вызванная неуверенностью. По разным оценкам, возвраты занимают от 10 до 30% времени чтения, при этом понимание растёт незначительно."},{"h":"Почему мы возвращаемся","p":"Причин три: низкая уверенность в себе, отвлечение внимания и привычка «перечитывать на всякий случай». Первые две лечатся средой и тренировкой, третья — правилом одного прохода."},{"h":"Как тренировать","p":"Ведите палец или карточку под строкой в ровном темпе: движение задаёт ритм и не даёт глазу откатиться. Читайте с установкой «я пойму с первого раза». Если мысль потеряна — дочитайте абзац до конца и вернитесь к нему целиком, а не к отдельной фразе. Возврат к абзацу — стратегия, возврат к слову — привычка."}],"bullets":["Правило одного прохода: сначала дочитать, потом оценить.","Отмечайте места возвратов карандашом — так вы увидите свои паттерны.","На сложном тексте возврат разрешён: это не ошибка, а инструмент."],"exercises":[{"type":"reader","title":"Один проход","xp":30,"instruction":"Прочитайте текст один раз. Правило: ни одного возврата. Ведите пальцем под строкой. После текста отметьте, сколько раз вам всё-таки захотелось вернуться.","params":{"textKey":"habits","mode":"onepass","countReturns":true,"questions":[{"q":"Из каких элементов состоит петля привычки?","options":["Сигнал, действие, награда","Цель, план, отчёт","Мотив, воля, результат"],"a":0,"explain":"Три звена: сигнал запускает, действие выполняется, награда закрепляет."},{"q":"Почему ежедневная короткая практика надёжнее редких рывков?","options":["Сигнал закрепляется, запуск перестаёт требовать воли","Так меньше устают глаза","Короткие тексты легче"],"a":0,"explain":"Привычка привязана к сигналу времени и места."},{"q":"Что делать со старой привычкой?","options":["Удалить навсегда","Заменить новой","Игнорировать"],"a":1,"explain":"Старую петлю почти нельзя стереть, но можно перекрыть новой."}]}},{"type":"reader","title":"Контроль возвратов","xp":20,"instruction":"Ещё один проход по тому же тексту — теперь с целью прочитать быстрее, чем в первый раз, и без возвратов.","params":{"textKey":"habits","mode":"onepass","countReturns":true,"questions":[{"q":"Что автор называет сигналом привычки?","options":["Время и место","Награду","Мотивацию"],"a":0,"explain":"В примере сигнал — время и место занятия."},{"q":"Почему награда может быть маленькой?","options":["Мозгу важен факт завершения","Награда не влияет","Большая награда вредна"],"a":0,"explain":"Достаточно отметить выполнение."}]}},{"type":"reader","title":"Один проход без возвратов","xp":20,"optional":true,"instruction":"Повторите правило одного прохода: палец под строкой, ни одного возврата.","params":{"textKey":"habits","mode":"onepass","countReturns":true,"questions":[{"q":"Что автор называет сигналом привычки?","options":["Время и место","Награду","Мотивацию"],"a":0,"explain":"В примере сигнал — время и место занятия."},{"q":"Почему награда может быть маленькой?","options":["Мозгу важен факт завершения","Награда не влияет","Большая награда вредна"],"a":0,"explain":"Достаточно отметить выполнение."}]}}],"quiz":{"xp":30,"questions":[{"q":"Что такое регрессия?","options":["Возврат глаза назад","Ускорение чтения","Остановка глаза"],"a":0,"explain":"Обратное движение по тексту."},{"q":"Сколько времени могут занимать возвраты?","options":["1–2%","10–30%","Более половины"],"a":1,"explain":"Оценки расходятся, но речь о десятках процентов."},{"q":"Какой возврат полезен?","options":["К отдельному слову при каждом сомнении","К абзацу, если потеряна мысль","К началу страницы всегда"],"a":1,"explain":"Возврат к смысловому блоку — стратегия."}]},"takeaway":"Один проход с уверенностью дешевле, чем три прохода с сомнением.","bonus":"Возьмите любую инструкцию и прочитайте её один раз, не возвращаясь. Затем проверьте по пунктам, что запомнили."},{"day":5,"phase":2,"title":"Чанкинг: читаем смысловыми блоками","subtitle":"Одна фиксация — два-три слова, а не одно","goal":"Сократить число фиксаций на строке за счёт укрупнения блоков.","minutes":20,"fig":"img/fig_chunk.png","fig_caption":"Разметка «/» показывает, где заканчивается смысловой блок.","theory":[{"h":"Почему по одному слову — медленно","p":"Каждая фиксация стоит времени, а смысл всё равно собирается из группы слов. Если глаз останавливается на каждом слове отдельно, вы платите за остановки больше, чем за понимание. Чанкинг — это привычка схватывать за одну остановку два-три коротких слова или одно длинное плюс служебное."},{"h":"Как выглядит разметка","p":"Возьмите абзац и поставьте косые черты там, где кончается смысловой блок: «Внимание / устроено как прожектор, / а не как ведро». Читайте по меткам, делая одну фиксацию на блок. Через несколько проходов метки убираются — глаз начинает группировать сам."},{"h":"Границы приёма","p":"Чем сложнее текст, тем мельче должны быть блоки. На договоре или формуле чанкинг до трёх слов может стоить понимания. Приём хорош на описательных, повествовательных и новостных текстах, где смысл движется ровно."}],"bullets":["Сначала с метками, потом без них.","Не расширяйте блок, пока понимание держится выше 70%.","Читайте блок как одно слово — без паузы внутри."],"exercises":[{"type":"reader","title":"Чтение с разметкой","xp":30,"instruction":"Включите разметку и читайте по блокам. Одна фиксация — один блок.","params":{"textKey":"music","mode":"chunk","marks":true,"chunkSize":2,"questions":[{"q":"Как называется способность подстраиваться под ритм?","options":["Слухо-моторная синхронизация","Абсолютный слух","Ритмическая память"],"a":0,"explain":"Связь слуха, движения и предсказания."},{"q":"Почему ритм помогает читать быстрее?","options":["Занимает речевой канал и задаёт темп","Улучшает зрение","Ускоряет дыхание"],"a":0,"explain":"Меньше ресурса остаётся на проговаривание."},{"q":"Когда внешний ритм мешает?","options":["На сложном тексте","На простом тексте","Никогда"],"a":0,"explain":"Смысл требует пауз и возвратов."}]}},{"type":"reader","title":"Без меток","xp":30,"instruction":"Тот же текст без разметки. Группируйте слова сами — взглядом, без пауз между словами.","params":{"textKey":"music","mode":"chunk","marks":false,"chunkSize":2,"questions":[{"q":"Что конкурирует с чтением сильнее — песня со словами или инструментальная музыка?","options":["Со словами","Инструментальная","Одинаково"],"a":0,"explain":"Текст песни конкурирует за речевые ресурсы."},{"q":"Что автор называет самым надёжным фоном?","options":["Тишину","Джаз","Белый шум"],"a":0,"explain":"Тишина — базовый вариант."}]}},{"type":"reader","title":"Блоки без меток","xp":20,"optional":true,"instruction":"Читайте блоками по 2–3 слова, но уже без разметки. Метки больше не нужны.","params":{"textKey":"sleep","mode":"chunk","marks":false,"chunkSize":3,"questions":[{"q":"Что происходит с выученным материалом во сне?","options":["Он стирается","Он закрепляется","Он не меняется"],"a":1,"explain":"Сон участвует в консолидации памяти."},{"q":"Почему невыспавшийся человек читает хуже?","options":["Страдает внимание и удержание смысла","У него хуже зрение","Он быстрее проговаривает"],"a":0,"explain":"Сон восстанавливает внимание."},{"q":"Заменяет ли кофеин сон?","options":["Да, полностью","Нет, он только блокирует сигнал усталости","Только утром"],"a":1,"explain":"Кофеин маскирует усталость, но не восстанавливает ресурс."}]}}],"quiz":{"xp":30,"questions":[{"q":"Сколько слов в блоке оптимально для начала?","options":["Одно","Два-три","Пять-шесть"],"a":1,"explain":"Начинают с двух-трёх коротких слов."},{"q":"Что делать, если понимание упало ниже 70%?","options":["Уменьшить блок","Увеличить блок","Читать быстрее"],"a":0,"explain":"Мельче блок — выше понимание."},{"q":"Где чанкинг рискован?","options":["В новостях","В договорах и формулах","В рассказах"],"a":1,"explain":"Там важна каждая деталь."}]},"takeaway":"Смысл живёт в блоках, а не в отдельных словах.","bonus":"Возьмите любой абзац и разметьте его чертами самостоятельно. Сравните свою разметку с логикой автора."},{"day":6,"phase":2,"title":"Сканирование и просмотр: читать выборочно","subtitle":"Не всякий текст нужно читать целиком","goal":"Освоить два режима выборочного чтения и научиться выбирать их по задаче.","minutes":20,"fig":"img/fig_skim.png","fig_caption":"Алгоритм трёхминутного обзора перед чтением.","theory":[{"h":"Два разных режима","p":"Сканирование — поиск конкретного факта: даты, имени, цифры, формулировки. Просмотр (skimming) — быстрый сбор общего смысла: о чём текст, какова структура, что автор доказывает. Это не «чтение по диагонали вместо чтения», а отдельные инструменты со своими задачами."},{"h":"Алгоритм обзора","p":"Сначала заголовки и подзаголовки — они дают скелет. Затем первые и последние предложения абзацев: там обычно тезис и вывод. Потом цифры, выделения, подписи к рисункам. И только после этого решайте, что читать подробно. Три минуты обзора экономят десять минут чтения."},{"h":"Сканирование по вопросу","p":"Сформулируйте, что именно ищете: «срок сдачи», «номер ответственного», «цена». Затем ведите глаз по тексту, выхватывая цифры, заголовки, имена. Ключевое слово ищите в разных формах: «срок», «сроки», «до». Не читайте всё, что попадается по пути."}],"bullets":["Обзор — не замена чтению, а подготовка к нему.","Сканирование всегда начинается с точного вопроса.","Проверяйте найденное в контексте: цифра без окружения обманчива."],"exercises":[{"type":"scan","title":"Сканирование программы","xp":30,"instruction":"У вас 90 секунд. Найдите ответы, не читая программу целиком.","params":{"textKey":"doc_schedule","seconds":90,"questions":[{"q":"В каком зале проходит пленарный доклад?","options":["204","210","212"],"a":0,"explain":"Зал 204, 10:00."},{"q":"Сколько мест на мастер-классе по таблицам Шульте?","options":["12","24","40"],"a":1,"explain":"Мест 24, запись у стойки."},{"q":"До какого времени выдают сертификаты?","options":["До 18:00","До 19:00","До 20:00"],"a":1,"explain":"До 19:00 на стойке регистрации."},{"q":"Когда публикуются видеозаписи пленарных докладов?","options":["20 марта","До 1 апреля","14 марта"],"a":1,"explain":"До 1 апреля; материалы — 20 марта."},{"q":"Кто ведёт мастер-класс?","options":["А. Ветров","М. Ковалёва","И. Лебедев"],"a":1,"explain":"Ведущая — М. Ковалёва."}]}},{"type":"scan","title":"Служебная записка: быстрый разбор","xp":30,"instruction":"60 секунд. Найдите ответы в записке о подготовке отчёта.","params":{"textKey":"modes","seconds":60,"questions":[{"q":"До какого числа принимаются черновики?","options":["Пятого","Десятого","Пятнадцатого"],"a":1,"explain":"Черновики — до десятого, отчёт — к пятнадцатому."},{"q":"Сколько страниц максимум в основном тексте?","options":["Восемь","Десять","Без ограничений"],"a":0,"explain":"Не более восьми страниц."},{"q":"Кто резервный ответственный?","options":["Марина Ковалёва","Игорь Лебедев","Аналитический отдел"],"a":1,"explain":"Резервный — И. Лебедев, 4317."},{"q":"Сколько времени даётся на ответ по замечаниям?","options":["Один день","Два рабочих дня","Неделя"],"a":1,"explain":"Два рабочих дня."}]}},{"type":"scan","title":"Поиск в служебной записке","xp":20,"optional":true,"instruction":"45 секунд. Найдите три факта в записке о подготовке отчёта.","params":{"textKey":"modes","seconds":45,"questions":[{"q":"Кто ответственный за сбор?","options":["Марина Ковалёва","Игорь Лебедев","Аналитический отдел"],"a":0,"explain":"М. Ковалёва, 4312."},{"q":"Как обозначаются пустые значения?","options":["Нулём","Прочерком","Пробелом"],"a":1,"explain":"Прочерк, а не ноль."},{"q":"Сколько этапов согласования?","options":["Один","Два","Три"],"a":1,"explain":"Профильный руководитель, затем аналитический отдел."}]}}],"quiz":{"xp":30,"questions":[{"q":"Чем сканирование отличается от просмотра?","options":["Сканирование ищет факт, просмотр собирает общий смысл","Это одно и то же","Сканирование медленнее"],"a":0,"explain":"Разные задачи — разные режимы."},{"q":"Что читать в первую очередь при обзоре?","options":["Первый абзац целиком","Заголовки и подзаголовки","Сноски"],"a":1,"explain":"Заголовки дают скелет текста."},{"q":"Зачем нужен точный вопрос перед сканированием?","options":["Чтобы глаз знал, что искать","Чтобы читать медленнее","Чтобы запомнить всё"],"a":0,"explain":"Вопрос задаёт фильтр."}]},"takeaway":"Выборочное чтение — не халтура, а инструмент под задачу.","bonus":"Откройте любую длинную инструкцию или статью и за три минуты составьте её скелет: 3–5 пунктов. Только после этого читайте."},{"day":7,"phase":2,"title":"SQ3R: вопросы до чтения","subtitle":"Читать с целью, а не «просто читать»","goal":"Освоить пятишаговую стратегию работы с учебным и деловым текстом.","minutes":20,"fig":"img/fig_sq3r.png","fig_caption":"Пять шагов SQ3R в адаптации под 20-минутное занятие.","theory":[{"h":"Почему вопросы работают","p":"Мозг ищет ответы активнее, чем просто принимает текст. Когда перед чтением сформулированы вопросы, внимание становится избирательным: вы замечаете то, что относится к делу, и быстрее отбрасываете шум. Это не мнемоника, а управление вниманием."},{"h":"Пять шагов","p":"Survey — обзор: заголовки, введение, выводы, выделения. Question — вопросы: превратите заголовки в вопросы. Read — чтение: ищите ответы, а не «проходите» текст. Recite — проговаривание: закройте текст и своими словами ответьте на вопросы. Review — проверка: вернитесь и сверьте, что упустили."},{"h":"Адаптация под 20 минут","p":"На обзор — 3 минуты, на вопросы — 2, на чтение — 10, на проговаривание и проверку — 5. Для короткой статьи шаги сжимаются до минут, но порядок сохраняется. Главное — не пропускать «Recite»: именно проговаривание превращает прочитанное в знание."}],"bullets":["Вопросы формулируйте до чтения, а не после.","Проговаривайте вслух или письменно — молчаливое «вроде понял» не считается.","Проверка занимает минуту, но спасает от иллюзии понимания."],"exercises":[{"type":"checklist","title":"Прогон SQ3R","xp":20,"instruction":"Пройдите шаги на любом тексте под рукой (статья, глава, инструкция). Отмечайте по факту выполнения.","params":{"items":["Survey: просмотрел заголовки, введение и выводы (3 минуты)","Question: превратил заголовки в 3–5 вопросов","Read: читал, ища ответы на свои вопросы","Recite: закрыл текст и пересказал главное своими словами","Review: вернулся и проверил, что упустил"]}},{"type":"reader","title":"Чтение с вопросами","xp":40,"instruction":"Сначала прочитайте вопросы, затем текст. Читайте, ища ответы. Потом ответьте, не подглядывая.","params":{"textKey":"memory","mode":"plain","preQuestions":true,"questions":[{"q":"Почему память сравнивают с реконструкцией, а не с архивом?","options":["Воспоминание собирается заново из фрагментов","Память хранит всё точно","Память не ошибается"],"a":0,"explain":"Каждый раз воспоминание пересобирается."},{"q":"Что укрепляет память сильнее — перечитывание или припоминание?","options":["Припоминание","Перечитывание","Одинаково"],"a":0,"explain":"Усилие по восстановлению закрепляет след."},{"q":"Какие интервалы повторения упоминаются?","options":["Через час и через день","Через день, три дня и неделю","Каждый день подряд"],"a":1,"explain":"Распределённое повторение."},{"q":"Почему ошибки при припоминании полезны?","options":["Показывают, где память проваливается","Учат не стараться","Ускоряют чтение"],"a":0,"explain":"Ошибка указывает на слабое место."}]}},{"type":"reader","title":"Текст с вопросами до чтения","xp":20,"optional":true,"instruction":"Сначала вопросы, потом текст. Читайте, ища ответы.","params":{"textKey":"language","mode":"plain","preQuestions":true,"questions":[{"q":"Что автор называет ярлыком, ускоряющим поиск?","options":["Название цвета","Букву","Интонацию"],"a":0,"explain":"Слово-название ускоряет категоризацию."},{"q":"Что растёт от чтения разнообразных текстов?","options":["Словарный запас и скорость понимания","Острота зрения","Скорость речи"],"a":0,"explain":"Опыт встреч с разными текстами — фундамент."}]}}],"quiz":{"xp":30,"questions":[{"q":"Что означает шаг Recite?","options":["Пересказ своими словами без подглядывания","Чтение вслух дословно","Запись текста"],"a":0,"explain":"Своими словами — ключевое условие."},{"q":"Зачем превращать заголовки в вопросы?","options":["Чтобы внимание искало ответы","Чтобы текст стал короче","Чтобы запомнить заголовки"],"a":0,"explain":"Вопрос задаёт избирательность."},{"q":"Сколько времени стоит отводить на обзор?","options":["30 секунд","Около 3 минут","Половину занятия"],"a":1,"explain":"Три минуты обзора экономят время на чтении."}]},"takeaway":"Сначала вопрос — потом текст. Так читают быстрее и запоминают лучше.","bonus":"Возьмите завтрашнюю статью или главу и выпишите 5 вопросов до чтения. После чтения проверьте, на все ли ответили."},{"day":8,"phase":2,"title":"Ритм: метроном, RSVP и упражнение 3-2-1","subtitle":"Внешний темп ломает плато","goal":"Прочитать текст быстрее привычного темпа, удержав понимание, и понять цену внешнего ритма.","minutes":20,"fig":"img/fig_pace.png","fig_caption":"Внешний темп задаёт скорость; понимание проверяется отдельно.","theory":[{"h":"Зачем нужен внешний ритм","p":"Внутренний темп у каждого свой и довольно устойчивый. Внешний стимул — метроном, подсветка, постукивание — заставляет идти быстрее, чем комфортно, и показывает, что прежний темп был привычкой, а не пределом. Это классический приём преодоления плато."},{"h":"RSVP","p":"Rapid Serial Visual Presentation — показ по одному слову (или короткому блоку) в центре экрана с заданной скоростью. Метод хорошо тренирует узнавание слов и убирает возвраты, но плохо подходит для сложных текстов: невозможно вернуться к формуле или перечитать фразу. Используйте его как разминку и как измеритель, а не как способ читать книги."},{"h":"Упражнение 3-2-1","p":"Возьмите отрывок, который читается за три минуты. Прочитайте его за три минуты, затем за две, затем за одну. Понимание проверяйте после каждого прохода. Смысл не в том, чтобы «успеть», а в том, чтобы увидеть: глаз и мозг справляются быстрее, чем вы думали. Если на третьем проходе понимание рассыпается — это и есть ваша честная граница."}],"bullets":["Один и тот же текст, три темпа, проверка после каждого.","На сложном тексте внешний ритм отключайте.","RSVP — тренажёр, а не формат чтения."],"exercises":[{"type":"reader","title":"RSVP: 350 слов в минуту","xp":30,"instruction":"Слова появляются в центре экрана. Не пытайтесь проговаривать — просто узнавайте. После окончания ответьте на вопросы.","params":{"textKey":"language","mode":"rsvp","wpm":350,"questions":[{"q":"Подтверждается ли сильная версия «нет слова — нет мысли»?","options":["Да","Нет","Только для цвета"],"a":1,"explain":"Люди различают оттенки без отдельных названий."},{"q":"Что ускоряет понимание при чтении?","options":["Богатый словарь и опыт разных текстов","Только упражнения для глаз","Более быстрый набор"],"a":0,"explain":"Знакомое слово узнаётся целиком."},{"q":"Как язык влияет на пространственные представления?","options":["Через привычные координаты описания","Никак","Только через письменность"],"a":0,"explain":"Абсолютные и относительные координаты тренируют разные навыки."}]}},{"type":"reader","title":"Пейсинг 420","xp":30,"instruction":"Тот же текст, но теперь подсветка идёт блоками со скоростью 420 слов/мин. Держитесь за подсветку.","params":{"textKey":"language","mode":"pacer","wpm":420,"questions":[{"q":"Что автор называет ярлыком, ускоряющим поиск?","options":["Название цвета","Букву","Интонацию"],"a":0,"explain":"Слово-название ускоряет категоризацию."},{"q":"Что растёт от чтения разнообразных текстов?","options":["Словарный запас и скорость понимания","Острота зрения","Скорость речи"],"a":0,"explain":"Опыт встреч с разными текстами — фундамент."}]}},{"type":"measure","title":"Босс фазы II: понимание под скоростью","xp":120,"instruction":"Финальный бой второй фазы. Прочитайте текст, ответьте на вопросы. Победа — не менее 380 слов/мин при понимании от 75%.","params":{"textKey":"practice","label":"Босс II","targetWpm":380,"minComp":75,"boss":true,"questions":[{"q":"Что делает практику осознанной?","options":["Конкретная цель и обратная связь","Большое количество повторений","Чтение без перерыва"],"a":0,"explain":"Без цели и обратной связи повторение не учит."},{"q":"Почему «просто больше читать» не всегда помогает?","options":["Без разбора ошибок закрепляются привычки","Чтение бесполезно","Нужны только сложные тексты"],"a":0,"explain":"Практика без коррекции закрепляет в том числе ошибки."},{"q":"Что такое зона ближайшего развития в тренировке?","options":["Задача чуть сложнее текущего уровня","Самая лёгкая задача","Задача на пределе возможностей без поддержки"],"a":0,"explain":"Сложность чуть выше текущей, но достижимая."},{"q":"Зачем нужна запись результатов?","options":["Чтобы видеть динамику и корректировать план","Чтобы отчитываться","Чтобы сравнивать с другими"],"a":0,"explain":"Обратная связь опирается на данные."},{"q":"Что важнее в тренировке — объём или качество обратной связи?","options":["Качество обратной связи","Объём любой ценой","Скорость выполнения"],"a":0,"explain":"Обратная связь направляет изменение."}]}},{"type":"reader","title":"Темп 450 на новом тексте","xp":20,"optional":true,"instruction":"Подсветка идёт быстрее. Держитесь за неё и проверьте, что осталось в памяти.","params":{"textKey":"memory","mode":"pacer","wpm":450,"questions":[{"q":"Почему память сравнивают с реконструкцией, а не с архивом?","options":["Воспоминание собирается заново из фрагментов","Память хранит всё точно","Память не ошибается"],"a":0,"explain":"Каждый раз воспоминание пересобирается."},{"q":"Что укрепляет память сильнее — перечитывание или припоминание?","options":["Припоминание","Перечитывание","Одинаково"],"a":0,"explain":"Усилие по восстановлению закрепляет след."},{"q":"Какие интервалы повторения упоминаются?","options":["Через час и через день","Через день, три дня и неделю","Каждый день подряд"],"a":1,"explain":"Распределённое повторение."},{"q":"Почему ошибки при припоминании полезны?","options":["Показывают, где память проваливается","Учат не стараться","Ускоряют чтение"],"a":0,"explain":"Ошибка указывает на слабое место."}]}}],"quiz":{"xp":30,"questions":[{"q":"Для чего RSVP подходит хуже всего?","options":["Для сложных текстов с формулами","Для разминки","Для замера темпа"],"a":0,"explain":"Нельзя вернуться и перечитать."},{"q":"В чём смысл упражнения 3-2-1?","options":["Увидеть, что прежний темп — привычка","Научиться читать за минуту любую книгу","Ускорить речь"],"a":0,"explain":"Оно показывает запас, а не волшебство."},{"q":"Что делать, если на ускорении понимание рассыпается?","options":["Зафиксировать границу и работать чуть ниже неё","Ускоряться дальше","Бросить упражнение"],"a":0,"explain":"Граница — рабочая информация."}]},"takeaway":"Темп можно менять. Понимание — условие, а не бонус.","bonus":"Проведите 3-2-1 на короткой статье: три минуты, две, одна. Запишите, на каком темпе понимание ещё держится."},{"day":9,"phase":3,"title":"Понимание: карта текста и вопросы к смыслу","subtitle":"Три уровня: факты, связи, вывод","goal":"Научиться быстро строить карту текста и проверять понимание на разных уровнях.","minutes":20,"fig":"img/fig_map.png","fig_caption":"Карта текста: тема, тезисы, аргументы, вывод.","theory":[{"h":"Понимание — это не одно умение","p":"Можно помнить факты и не видеть связей. Можно уловить общий смысл и перепутать детали. Поэтому проверка понимания идёт на трёх уровнях: что сказано (факты), как связано (связи, причины), что следует (вывод, применение). Быстрое чтение чаще всего ломается на втором уровне."},{"h":"Карта текста","p":"После чтения нарисуйте простую схему: тема в центре, 3–4 тезиса вокруг, под каждым — аргумент или пример. Не переписывайте текст, а восстанавливайте структуру по памяти. Карта занимает две минуты и показывает, где именно провал."},{"h":"Вопросы, которые работают","p":"«Что автор доказывает?», «На чём это держится?», «Что из этого следует для меня?». Три вопроса — три уровня. Если ответ на третий не находится, текст не присвоен: вы его просмотрели, а не прочитали."}],"bullets":["Карту стройте по памяти, а не с открытым текстом.","Факт без связи — это шум.","Вывод формулируйте своими словами, коротко."],"exercises":[{"type":"reader","title":"Чтение с картой","xp":30,"instruction":"Прочитайте текст, затем закройте его и ответьте на вопросы трёх уровней.","params":{"textKey":"reading","mode":"plain","questions":[{"q":"Как называется остановка глаза на слове?","options":["Фиксация","Саккада","Регрессия"],"a":0,"explain":"Фиксация — задержка, саккада — перескок."},{"q":"Почему возвраты часто не помогают?","options":["Они происходят автоматически, из неуверенности","Они всегда улучшают понимание","Они ускоряют чтение"],"a":0,"explain":"Часто это привычка, а не необходимость."},{"q":"Что тормозит чтение при быстром темпе?","options":["Внутреннее проговаривание","Размер шрифта","Длина строки"],"a":0,"explain":"Речь не успевает за глазами."},{"q":"Из каких четырёх факторов складывается практика скорочтения?","options":["Фиксации, поле зрения, возвраты, проговаривание","Свет, поза, бумага, ручка","Внимание, сон, спорт, питание"],"a":0,"explain":"Это и есть механика чтения."},{"q":"Почему нельзя «отключить» внутренний голос навсегда?","options":["Он помогает понимать сложные тексты","Он не существует","Это запрещено методикой"],"a":0,"explain":"Речь участвует в понимании."}]}},{"type":"checklist","title":"Карта по памяти","xp":20,"instruction":"Нарисуйте карту последнего текста на бумаге за две минуты, не подглядывая. Отметьте, что получилось.","params":{"items":["Тема сформулирована одной фразой","Выделено 3–4 тезиса","Под каждый тезис найден аргумент или пример","Сформулирован собственный вывод","Отмечено, что осталось непонятным"]}},{"type":"reader","title":"Карта на скорости 380","xp":20,"optional":true,"instruction":"Прочитайте текст под темп и ответьте на вопросы: это проверка связей, а не деталей.","params":{"textKey":"reading","mode":"pacer","wpm":380,"questions":[{"q":"Как называется остановка глаза на слове?","options":["Фиксация","Саккада","Регрессия"],"a":0,"explain":"Фиксация — задержка, саккада — перескок."},{"q":"Почему возвраты часто не помогают?","options":["Они происходят автоматически, из неуверенности","Они всегда улучшают понимание","Они ускоряют чтение"],"a":0,"explain":"Часто это привычка, а не необходимость."},{"q":"Что тормозит чтение при быстром темпе?","options":["Внутреннее проговаривание","Размер шрифта","Длина строки"],"a":0,"explain":"Речь не успевает за глазами."},{"q":"Из каких четырёх факторов складывается практика скорочтения?","options":["Фиксации, поле зрения, возвраты, проговаривание","Свет, поза, бумага, ручка","Внимание, сон, спорт, питание"],"a":0,"explain":"Это и есть механика чтения."},{"q":"Почему нельзя «отключить» внутренний голос навсегда?","options":["Он помогает понимать сложные тексты","Он не существует","Это запрещено методикой"],"a":0,"explain":"Речь участвует в понимании."}]}}],"quiz":{"xp":30,"questions":[{"q":"Сколько уровней понимания выделяет урок?","options":["Два","Три","Пять"],"a":1,"explain":"Факты, связи, вывод."},{"q":"Когда строится карта текста?","options":["По памяти после чтения","Во время чтения с подглядыванием","Вместо чтения"],"a":0,"explain":"Именно поэтому она показывает реальное понимание."},{"q":"Что означает «текст не присвоен»?","options":["Вы не можете сформулировать вывод своими словами","Вы не запомнили дату","Вы читали медленно"],"a":0,"explain":"Вывод — признак присвоения."}]},"takeaway":"Проверяйте не «прочитал ли», а «что осталось».","bonus":"Перескажите вчерашний текст вслух за 60 секунд. Запишите, что выпало."},{"day":10,"phase":3,"title":"Память: активное припоминание и интервалы","subtitle":"Закрыть книгу — самый полезный момент чтения","goal":"Освоить припоминание и интервальное повторение, вести заметки по Корнеллу.","minutes":20,"fig":"img/fig_memory.png","fig_caption":"Кривая забывания и интервалы повторения: 1–3–7–14 дней.","theory":[{"h":"Перечитывание обманывает","p":"Когда текст перед глазами, он кажется знакомым, и возникает ощущение «я знаю». Это узнавание, а не память. Знание проверяется только без текста. Поэтому главное упражнение — закрыть источник и вспомнить: сначала свободно, потом по вопросам."},{"h":"Интервалы","p":"Повторение через день, три дня, неделю и две недели даёт больше, чем многократное повторение подряд. Между подходами след слабеет — и усилие по его восстановлению как раз укрепляет память. Это и есть механизм интервального повторения."},{"h":"Заметки по Корнеллу","p":"Лист делится на три зоны: широкое поле для заметок, узкая колонка слева для вопросов и ключевых слов, нижняя полоса для вывода. Через день закройте заметки и ответьте на вопросы из левой колонки. Это превращает конспект из склада в тренажёр."}],"bullets":["Сначала вспомните, потом проверьте.","Вопросы в левой колонке — ваша будущая проверка.","Ошибка при припоминании полезнее гладкого перечитывания."],"exercises":[{"type":"reader","title":"Текст под припоминание","xp":20,"instruction":"Прочитайте текст один раз. Читайте внимательно: дальше текст закроется.","params":{"textKey":"caffeine","mode":"plain","showQuestionsAfter":false,"questions":[]}},{"type":"recall","title":"Свободное припоминание","xp":40,"instruction":"Текст скрыт. Напишите всё, что запомнили, своими словами — 2 минуты. Затем система покажет, какие ключевые пункты вы задели.","params":{"textKey":"caffeine","seconds":120,"keywords":["аденозин","пять часов","полувыведение","сон","внимание","тревожность","привыкание","недосып","шесть-восемь","индикатор"]}},{"type":"checklist","title":"Заметки по Корнеллу","xp":20,"instruction":"Сделайте такие заметки по любому прочитанному сегодня тексту. Отметьте пункты.","params":{"items":["Лист разделён на три зоны","Слева записаны 3–5 вопросов","В основной зоне — тезисы, а не сплошной текст","Внизу сформулирован вывод одной фразой","Через день я отвечу на вопросы, закрыв заметки"]}},{"type":"recall","title":"Припоминание: текст о памяти","xp":25,"optional":true,"instruction":"Прочитайте текст, закройте его и напишите всё, что запомнили.","params":{"textKey":"memory","seconds":120,"keywords":["реконструкция","перечитывание","припоминание","интервалы","ошибки","след","смысл","закрыть книгу"]}}],"quiz":{"xp":30,"questions":[{"q":"Что даёт больше для памяти?","options":["Перечитывание","Припоминание без текста","Подчёркивание маркером"],"a":1,"explain":"Усилие по восстановлению закрепляет след."},{"q":"Какие интервалы повторения полезны?","options":["Каждый час","1–3–7–14 дней","Раз в месяц"],"a":1,"explain":"Распределённые интервалы."},{"q":"Зачем нужна левая колонка в заметках Корнелла?","options":["Для вопросов и ключевых слов","Для рисунков","Для ссылок"],"a":0,"explain":"По ней вы проверяете себя позже."}]},"takeaway":"Память строится усилием, а не повторным взглядом.","bonus":"Возьмите вчерашний текст и воспроизведите три главных тезиса без подглядывания. Проверьте."},{"day":11,"phase":3,"title":"Концентрация: внимание как рабочая мышца","subtitle":"Убрать утечки и работать короткими спринтами","goal":"Научиться входить в рабочий режим за минуту и удерживать его 10 минут.","minutes":20,"fig":"img/fig_attention.png","fig_caption":"Каждое переключение оставляет «остаток внимания» и стоит времени.","theory":[{"h":"Остаток внимания","p":"После переключения на сообщение часть внимания остаётся на прежней задаче. Это явление называют остатком внимания: человек вернулся к тексту, но первые секунды всё ещё думает о другом. Чем чаще переключения, тем больше времени уходит на «въезд» обратно."},{"h":"Спринт","p":"Рабочий спринт — это короткий отрезок с одной задачей и таймером: 10–15 минут чтения без телефона, переключений и вкладок. Перед началом сформулируйте одну цель: «прочитать раздел и выписать три тезиса». После — короткая пауза с движением, а не с лентой."},{"h":"Парковка мыслей","p":"Если во время чтения вспомнилось дело, не переключайтесь: запишите его одной строкой на лист «парковка» и вернитесь к тексту. Так мысль не потеряна и внимание не потрачено."}],"bullets":["Одна задача — один таймер.","Телефон — вне поля зрения, а не просто «экраном вниз».","Пауза — движение или окно, а не лента."],"exercises":[{"type":"reader","title":"Спринт 10 минут","xp":30,"instruction":"Одна цель: прочитать и удержать мысль. Таймер идёт. Не переключайтесь. После — вопросы.","params":{"textKey":"movement","mode":"pacer","wpm":360,"questions":[{"q":"Что происходит с вниманием после короткой разминки?","options":["Восстанавливается лучше, чем после телефона","Ухудшается","Не меняется"],"a":0,"explain":"Движение и смена контекста помогают."},{"q":"Что автор советует делать, если чтение идёт тяжело?","options":["Сделать паузу и походить","Увеличить усилие","Читать быстрее"],"a":0,"explain":"Смена состояния эффективнее давления."},{"q":"Что важнее в двигательной активности?","options":["Регулярность","Интенсивность","Длительность одного раза"],"a":0,"explain":"Регулярность важнее интенсивности."}]}},{"type":"reflection","title":"Мои утечки внимания","xp":20,"instruction":"Назовите три конкретные утечки, которые мешают вам читать, и по одному действию против каждой.","params":{"prompt":"Три утечки внимания и что я с ними сделаю","placeholder":"Например: телефон на столе → убираю в ящик; вкладки с новостями → закрываю перед спринтом…","minChars":60}},{"type":"reader","title":"Спринт под темп 420","xp":20,"optional":true,"instruction":"Одна задача: удержать мысль под подсветкой. Без переключений.","params":{"textKey":"movement","mode":"pacer","wpm":420,"questions":[{"q":"Что происходит с вниманием после короткой разминки?","options":["Восстанавливается лучше, чем после телефона","Ухудшается","Не меняется"],"a":0,"explain":"Движение и смена контекста помогают."},{"q":"Что автор советует делать, если чтение идёт тяжело?","options":["Сделать паузу и походить","Увеличить усилие","Читать быстрее"],"a":0,"explain":"Смена состояния эффективнее давления."},{"q":"Что важнее в двигательной активности?","options":["Регулярность","Интенсивность","Длительность одного раза"],"a":0,"explain":"Регулярность важнее интенсивности."}]}}],"quiz":{"xp":30,"questions":[{"q":"Что такое остаток внимания?","options":["Часть внимания, оставшаяся на прежней задаче","Усталость глаз","Привычка возвращаться"],"a":0,"explain":"Он замедляет возврат в контекст."},{"q":"Зачем нужна «парковка мыслей»?","options":["Записать отвлечение и вернуться к тексту","Запомнить всё сразу","Ускорить чтение"],"a":0,"explain":"Так мысль сохранена, а внимание не потрачено."},{"q":"Чем полезна пауза после спринта?","options":["Движением и сменой контекста","Проверкой сообщений","Продолжением чтения без перерыва"],"a":0,"explain":"Лента возвращает утечку."}]},"takeaway":"Внимание — не характер, а режим. Режим настраивается.","bonus":"Проведите один спринт 10 минут с листом «парковка» рядом. Посчитайте, сколько мыслей удалось отложить."},{"day":12,"phase":4,"title":"Гибкая скорость: четыре режима чтения","subtitle":"Не читайте всё одинаково","goal":"Научиться выбирать режим чтения под задачу и переключаться между ними.","minutes":20,"fig":"img/fig_modes.png","fig_caption":"Матрица режимов: цель определяет скорость и глубину.","theory":[{"h":"Четыре режима","p":"Поиск (сканирование) — найти конкретный факт, скорость максимальная, понимание локальное. Просмотр — понять общий смысл и структуру, скорость высокая. Обычное чтение — понять и удержать, скорость средняя. Глубокое чтение — разобрать логику, формулы, риски, скорость низкая. Ошибка — читать всё в одном режиме."},{"h":"Цена ошибки","p":"Если договор читать просмотром, можно пропустить условие. Если новость читать глубоко, вы потратите время на то, что не нужно удерживать. Гибкость — это не умение читать быстро, а умение выбирать темп под риск ошибки."},{"h":"Переключение","p":"Режим задаётся до чтения тремя вопросами: зачем я читаю, что должно остаться после, что будет, если я пропущу деталь. Ответы определяют темп. Внутри текста режим можно менять: обзор → глубокое чтение ключевого раздела → просмотр остального."}],"bullets":["Сначала цель, потом скорость.","Высокий риск ошибки — низкая скорость.","Переключайтесь внутри текста, а не только между текстами."],"exercises":[{"type":"flexmatch","title":"Выберите режим","xp":30,"instruction":"Для каждой ситуации выберите подходящий режим. Ошибки разберём сразу.","params":{"modes":[{"id":"scan","label":"Поиск"},{"id":"skim","label":"Просмотр"},{"id":"normal","label":"Обычное чтение"},{"id":"deep","label":"Глубокое чтение"}],"pairs":[{"scenario":"Нужно узнать дату сдачи отчёта в длинной инструкции","answer":"scan","explain":"Ищем один факт — сканирование."},{"scenario":"Перед совещанием нужно понять, о чём статья на 8 страниц","answer":"skim","explain":"Нужен общий смысл и структура."},{"scenario":"Читаете главу учебника, чтобы разобраться в теме","answer":"normal","explain":"Нужно понять и удержать."},{"scenario":"Проверяете условия договора перед подписанием","answer":"deep","explain":"Высокий риск ошибки — низкая скорость."},{"scenario":"Ищете в расписании свою секцию","answer":"scan","explain":"Конкретный факт."},{"scenario":"Просматриваете ленту новостей за день","answer":"skim","explain":"Достаточно общего смысла."}]}},{"type":"scan","title":"Поиск в служебной записке","xp":20,"instruction":"45 секунд. Найдите ответы — это режим поиска.","params":{"textKey":"modes","seconds":45,"questions":[{"q":"Кто ответственный за сбор?","options":["Марина Ковалёва","Игорь Лебедев","Аналитический отдел"],"a":0,"explain":"М. Ковалёва, 4312."},{"q":"Как обозначаются пустые значения?","options":["Нулём","Прочерком","Пробелом"],"a":1,"explain":"Прочерк, а не ноль."},{"q":"Сколько этапов согласования?","options":["Один","Два","Три"],"a":1,"explain":"Профильный руководитель, затем аналитический отдел."}]}},{"type":"flexmatch","title":"Ещё четыре ситуации","xp":20,"optional":true,"instruction":"Выберите режим для каждой ситуации. Ошибки разберём сразу.","params":{"modes":[{"id":"scan","label":"Поиск"},{"id":"skim","label":"Просмотр"},{"id":"normal","label":"Обычное чтение"},{"id":"deep","label":"Глубокое чтение"}],"pairs":[{"scenario":"Нужно узнать цену в прайс-листе на 40 страниц","answer":"scan","explain":"Один факт — сканирование."},{"scenario":"Просматриваете три статьи, чтобы выбрать одну для чтения","answer":"skim","explain":"Общий смысл и структура."},{"scenario":"Читаете инструкцию к прибору перед первым запуском","answer":"deep","explain":"Высокий риск ошибки."},{"scenario":"Читаете главу, чтобы обсудить её на семинаре","answer":"normal","explain":"Нужно понять и удержать."}]}}],"quiz":{"xp":30,"questions":[{"q":"Что определяет режим чтения?","options":["Цель и цена ошибки","Настроение","Длина текста"],"a":0,"explain":"Задача задаёт темп."},{"q":"Договор перед подписанием — какой режим?","options":["Поиск","Просмотр","Глубокое чтение"],"a":2,"explain":"Высокий риск ошибки."},{"q":"Где чаще всего ошибаются?","options":["Читают всё в одном режиме","Слишком часто меняют режим","Читают слишком медленно"],"a":0,"explain":"Одна скорость на все задачи — главная ошибка."}]},"takeaway":"Скорость — это инструмент, а не цель. Цель — нужный результат.","bonus":"Возьмите три своих обычных текста и заранее определите для каждого режим. Проверьте, совпал ли он с фактическим."},{"day":13,"phase":4,"title":"Проект: реальный текст по протоколу","subtitle":"Собираем всё вместе на длинном материале","goal":"Пройти полный цикл: обзор → вопросы → чтение → припоминание → заметки.","minutes":20,"fig":"img/fig_protocol.png","fig_caption":"Протокол работы с реальным текстом за 20 минут.","theory":[{"h":"Зачем протокол","p":"Навык рассыпается, когда его применяют хаотично. Протокол задаёт порядок: обзор, вопросы, чтение, припоминание, заметки. Он же защищает от главной ошибки — начать читать с первой строки и потерять структуру."},{"h":"Как это выглядит на практике","p":"Минута на обзор: заголовки, введение, вывод. Минута на вопросы: что я хочу узнать. Десять минут чтения с целью. Две минуты на припоминание без текста. Пять минут на заметки и вывод. Итого — около двадцати минут, и текст остаётся в голове, а не на странице."},{"h":"Что считается результатом","p":"Не количество страниц, а три вещи: вы можете пересказать главное, вы знаете, где искать детали, вы сформулировали своё отношение или применение. Всё остальное — приятный бонус."}],"bullets":["Обзор всегда до чтения.","Припоминание — сразу после, пока текст свеж.","Заметки — короткие, своими словами."],"exercises":[{"type":"measure","title":"Длинный текст: контрольный замер","xp":50,"instruction":"Прочитайте текст в удобном темпе, но с установкой понять структуру. Затем ответьте на вопросы.","params":{"textKey":"long_essay","label":"Проект","targetWpm":400,"minComp":70,"questions":[{"q":"Почему понятность зависит от читателя?","options":["Это отношение текста и подготовленности читателя","Текст всегда понятен одинаково","Понятность определяется длиной"],"a":0,"explain":"Специалист и новичок читают по-разному."},{"q":"Какой признак связан со структурой?","options":["Заголовки, короткие абзацы, связки","Много терминов","Длинные предложения"],"a":0,"explain":"Структура экономит усилия на ориентацию."},{"q":"Почему конкретика полезна?","options":["Делает мысль проверяемой","Сокращает текст","Убирает вывод"],"a":0,"explain":"Действие проверяемо, абстракция — нет."},{"q":"Зачем нужна избыточность?","options":["Повторяет главное разными способами","Увеличивает объём","Скрывает смысл"],"a":0,"explain":"Страховка от пропуска."},{"q":"Что автор советует делать перед быстрым чтением?","options":["Посмотреть заголовки и выводы","Читать с первой строки","Сразу ускоряться"],"a":0,"explain":"Обзор задаёт карту."},{"q":"Что превращает потребление в работу?","options":["Вопрос к тексту","Скорость","Тишина"],"a":0,"explain":"Вопрос задаёт цель."}]}},{"type":"checklist","title":"Протокол на реальном материале","xp":20,"instruction":"Примените протокол к реальной статье или главе (не из курса). Отметьте шаги.","params":{"items":["Обзор: заголовки, введение, вывод — 1–3 минуты","Вопросы: 3 вопроса до чтения","Чтение с целью — 10 минут","Припоминание без текста — 2 минуты","Заметки и вывод — 5 минут"]}},{"type":"reflection","title":"Что сработало","xp":20,"instruction":"Опишите, где протокол помог и где вы сорвались. Это важнее оценки «получилось / не получилось».","params":{"prompt":"Что сработало и что сорвалось","placeholder":"Например: обзор помог, но на этапе вопросов я застрял…","minChars":60}},{"type":"scan","title":"Поиск по длинному тексту","xp":20,"optional":true,"instruction":"90 секунд. Найдите ответы в длинном тексте, не читая его целиком.","params":{"textKey":"long_essay","seconds":90,"questions":[{"q":"Почему понятность зависит от читателя?","options":["Это отношение текста и подготовленности читателя","Текст всегда понятен одинаково","Понятность определяется длиной"],"a":0,"explain":"Специалист и новичок читают по-разному."},{"q":"Какой признак связан со структурой?","options":["Заголовки, короткие абзацы, связки","Много терминов","Длинные предложения"],"a":0,"explain":"Структура экономит усилия на ориентацию."},{"q":"Почему конкретика полезна?","options":["Делает мысль проверяемой","Сокращает текст","Убирает вывод"],"a":0,"explain":"Действие проверяемо, абстракция — нет."},{"q":"Зачем нужна избыточность?","options":["Повторяет главное разными способами","Увеличивает объём","Скрывает смысл"],"a":0,"explain":"Страховка от пропуска."},{"q":"Что автор советует делать перед быстрым чтением?","options":["Посмотреть заголовки и выводы","Читать с первой строки","Сразу ускоряться"],"a":0,"explain":"Обзор задаёт карту."},{"q":"Что превращает потребление в работу?","options":["Вопрос к тексту","Скорость","Тишина"],"a":0,"explain":"Вопрос задаёт цель."}]}}],"quiz":{"xp":30,"questions":[{"q":"С чего начинается протокол?","options":["С обзора","С чтения первой строки","С заметок"],"a":0,"explain":"Обзор даёт структуру."},{"q":"Что считается результатом работы с текстом?","options":["Умение пересказать, найти детали, применить","Количество страниц","Скорость"],"a":0,"explain":"Три признака присвоения."},{"q":"Когда лучше припоминать?","options":["Сразу после чтения","Через неделю","Никогда"],"a":0,"explain":"Пока материал свеж."}]},"takeaway":"Навык — это протокол, который выполняется без героизма.","bonus":"Выберите книгу, которую давно откладывали, и прочитайте одну главу по протоколу. Запишите три тезиса."},{"day":14,"phase":4,"title":"Финал: сравнение, мифы и план на 30 дней","subtitle":"Что вы получили и что делать дальше","goal":"Сравнить финальный замер с базой, проверить знания и составить план поддержания навыка.","minutes":20,"fig":"img/fig_progress.png","fig_caption":"Реалистичная динамика: скорость растёт, понимание удерживается проверкой.","theory":[{"h":"Что сравнивать","p":"Сравнивайте не абсолютные цифры, а эффективную скорость и понимание. Если скорость выросла в полтора раза, а понимание осталось на уровне 70–80%, это хороший результат двух недель. Если скорость выросла, а понимание упало до 50%, вы тренировали листание."},{"h":"Чего ждать дальше","p":"Навык держится, пока есть практика. Оптимальный режим поддержания — 15–20 минут в день: один короткий текст по протоколу и один тренажёр. Раз в неделю — замер, чтобы видеть динамику. Раз в месяц — пересмотр режимов чтения под новые задачи."},{"h":"Мифы, которые стоит отпустить","p":"Тысяча слов в минуту с полным пониманием — реклама, а не результат. Чтение по диагонали сложных текстов — потеря смысла. Гимнастика для глаз не учит читать быстрее. «Активация полушарий» и фоточтение — псевдонаука. Реальный прогресс скромнее и надёжнее: меньше возвратов, шире захват, лучше структура, честная проверка."}],"bullets":["Сравнивайте эффективную скорость, а не только скорость.","Планируйте 15–20 минут в день, а не подвиг раз в месяц.","Проверяйте понимание всегда — иначе тренируете имитацию."],"exercises":[{"type":"measure","title":"Финальный замер","xp":100,"instruction":"Последний замер. Читайте в темпе, который считаете рабочим. Победа — от 380 слов/мин при понимании от 75%.","params":{"textKey":"final_essay","label":"Финал","targetWpm":380,"minComp":75,"boss":true,"questions":[{"q":"Почему скорость без цели не имеет смысла?","options":["Разные задачи требуют разного темпа","Скорость всегда вредна","Цель не важна"],"a":0,"explain":"Параметр имеет смысл только в задаче."},{"q":"Что ограничивает скорость чтения?","options":["Обработка смысла","Размер шрифта","Длина строки"],"a":0,"explain":"Глаз может быстрее, чем понимание."},{"q":"Что такое эффективная скорость?","options":["Скорость с учётом понимания","Максимальная скорость","Скорость без возвратов"],"a":0,"explain":"Слов/мин × понимание."},{"q":"Какой прогресс за 2–3 недели считается реалистичным?","options":["В 1,5–2 раза при сохранении понимания","В 5 раз","Нулевой"],"a":0,"explain":"Более смелые обещания — за счёт пропуска текста."},{"q":"Что работает хуже всего?","options":["Гимнастика для глаз и «активация полушарий»","Устранение возвратов","Предварительный обзор"],"a":0,"explain":"Это мифы."},{"q":"Что удерживает навык?","options":["Регулярная практика с обратной связью","Одно интенсивное занятие","Покупка приложения"],"a":0,"explain":"Практика и обратная связь."}]}},{"type":"reflection","title":"План на 30 дней","xp":30,"instruction":"Составьте конкретный план: что читаете, когда, каким режимом, как проверяете.","params":{"prompt":"Мой план на 30 дней","placeholder":"15 минут в день: 1 текст по протоколу + 1 тренажёр. Раз в неделю — замер. Книга: …","minChars":80}},{"type":"reflection","title":"Что изменилось","xp":25,"optional":true,"instruction":"Сравните себя с первым днём: что стало проще, что осталось трудным.","params":{"prompt":"Что изменилось за 14 дней","minChars":60,"placeholder":"Например: перестал перечитывать абзацы; Шульте с 70 до 48 секунд; сложным остаётся проговаривание…"}}],"quiz":{"xp":40,"questions":[{"q":"Какое утверждение верно?","options":["1000 слов/мин с полным пониманием — реальный результат тренировки","Реалистичный рост за 2–3 недели — примерно в 1,5–2 раза","Скорость важнее понимания"],"a":1,"explain":"Скромный, но проверяемый рост."},{"q":"Что делать, если понимание упало ниже 70%?","options":["Снизить темп","Ускориться","Не проверять понимание"],"a":0,"explain":"Понимание — условие."},{"q":"Что из перечисленного — миф?","options":["Возвраты можно сократить","Поле зрения можно расширить тренировкой","Фоточтение активирует правое полушарие"],"a":2,"explain":"Фоточтение — псевдонаука."}]},"takeaway":"Вы прошли цикл. Теперь навык держится практикой, а не курсом.","bonus":"Перечитайте свой ответ из первого дня. Сравните задачи «зачем мне это» с тем, что получилось."}]};
